  1→package com.anthropic.eclipse.claude.views;
  2→
  3→import org.eclipse.swt.SWT;
  4→import org.eclipse.swt.custom.SashForm;
  5→import org.eclipse.swt.custom.StyledText;
  6→import org.eclipse.swt.events.*;
  7→import org.eclipse.swt.graphics.*;
  8→import org.eclipse.swt.layout.*;
  9→import org.eclipse.swt.widgets.*;
 10→import org.eclipse.ui.part.ViewPart;
 11→import com.anthropic.eclipse.claude.api.ClaudeApiClient;
 12→
 13→/**
 14→ * The main Claude AI Chat view panel.
 15→ * Shows conversation history and input area.
 16→ */
 17→public class ClaudeChatView extends ViewPart {
 18→
 19→    public static final String ID = "com.anthropic.eclipse.claude.views.ClaudeChatView";
 20→
 21→    private StyledText chatDisplay;
 22→    private Text inputText;
 23→    private Button sendButton;
 24→    private Button clearButton;
 25→    private Label statusLabel;
 26→    private ClaudeApiClient apiClient;
 27→    private boolean isLoading = false;
 28→
 29→    // Colors
 30→    private Color userBgColor;
 31→    private Color claudeBgColor;
 32→    private Color userTextColor;
 33→    private Color claudeTextColor;
 34→    private Font codeFont;
 35→
 36→    @Override
 37→    public void createPartControl(Composite parent) {
 38→        apiClient = new ClaudeApiClient();
 39→
 40→        // Initialize colors
 41→        Display display = parent.getDisplay();
 42→        userBgColor = new Color(display, 230, 244, 255);
 43→        claudeBgColor = new Color(display, 245, 245, 245);
 44→        userTextColor = new Color(display, 0, 70, 140);
 45→        claudeTextColor = new Color(display, 30, 30, 30);
 46→        codeFont = new Font(display, "Courier New", 10, SWT.NORMAL);
 47→
 48→        // Main layout
 49→        parent.setLayout(new GridLayout(1, false));
 50→
 51→        // Top toolbar
 52→        createToolbar(parent);
 53→
 54→        // SashForm: chat display + input area
 55→        SashForm sash = new SashForm(parent, SWT.VERTICAL);
 56→        sash.setLayoutData(new GridData(SWT.FILL, SWT.FILL, true, true));
 57→
 58→        // Chat display
 59→        createChatDisplay(sash);
 60→
 61→        // Input area
 62→        createInputArea(sash);
 63→
 64→        sash.setWeights(new int[]{75, 25});
 65→
 66→        // Status bar
 67→        statusLabel = new Label(parent, SWT.NONE);
 68→        statusLabel.setLayoutData(new GridData(SWT.FILL, SWT.BOTTOM, true, false));
 69→        statusLabel.setText("Ready. Type a message and press Enter or click Send.");
 70→
 71→        // Welcome message
 72→        appendMessage("Claude", "שלום! אני Claude, עוזר ה-AI שלך. אוכל לעזור לך עם:\n" +
 73→            "• ניתוח קוד COBOL\n" +
 74→            "• הסבר והבנת קוד\n" +
 75→            "• איתור באגים ושיפורים\n" +
 76→            "• שאלות כלליות\n\n" +
 77→            "לשלוח קוד נבחר: לחץ ימני בעורך > Claude AI > Send to Claude\n" +
 78→            "קיצור מקשים: Ctrl+Shift+S", false);
 79→
 80→        // Dispose listener
 81→        parent.addDisposeListener(e -> {
 82→            if (userBgColor != null) userBgColor.dispose();
 83→            if (claudeBgColor != null) claudeBgColor.dispose();
 84→            if (userTextColor != null) userTextColor.dispose();
 85→            if (claudeTextColor != null) claudeTextColor.dispose();
 86→            if (codeFont != null) codeFont.dispose();
 87→        });
 88→    }
 89→
 90→    private void createToolbar(Composite parent) {
 91→        Composite toolbar = new Composite(parent, SWT.NONE);
 92→        toolbar.setLayoutData(new GridData(SWT.FILL, SWT.TOP, true, false));
 93→        toolbar.setLayout(new GridLayout(3, false));
 94→
 95→        Label title = new Label(toolbar, SWT.NONE);
 96→        title.setText("Claude AI Chat");
 97→        FontData[] fds = title.getFont().getFontData();
 98→        fds[0].setStyle(SWT.BOLD);
 99→        fds[0].setHeight(11);
100→        title.setFont(new Font(parent.getDisplay(), fds));
101→        title.setLayoutData(new GridData(SWT.FILL, SWT.CENTER, true, false));
102→
103→        clearButton = new Button(toolbar, SWT.PUSH);
104→        clearButton.setText("Clear Chat");
105→        clearButton.addSelectionListener(new SelectionAdapter() {
106→            @Override
107→            public void widgetSelected(SelectionEvent e) {
108→                chatDisplay.setText("");
109→                apiClient.clearHistory();
110→                statusLabel.setText("Conversation cleared.");
111→                appendMessage("Claude", "שיחה חדשה. איך אוכל לעזור?", false);
112→            }
113→        });
114→
115→        Button prefsButton = new Button(toolbar, SWT.PUSH);
116→        prefsButton.setText("⚙ Settings");
117→        prefsButton.addSelectionListener(new SelectionAdapter() {
118→            @Override
119→            public void widgetSelected(SelectionEvent e) {
120→                org.eclipse.ui.dialogs.PreferencesUtil.createPreferenceDialogOn(
121→                    getSite().getShell(),
122→                    "com.anthropic.eclipse.claude.preferences.ClaudePreferencePage",
123→                    null, null).open();
124→            }
125→        });
126→    }
127→
128→    private void createChatDisplay(Composite parent) {
129→        chatDisplay = new StyledText(parent, SWT.MULTI | SWT.READ_ONLY | SWT.WRAP | SWT.V_SCROLL | SWT.BORDER);
130→        chatDisplay.setEditable(false);
131→        chatDisplay.setWordWrap(true);
132→        chatDisplay.setLeftMargin(8);
133→        chatDisplay.setRightMargin(8);
134→        chatDisplay.setTopMargin(8);
135→        chatDisplay.setLineSpacing(3);
136→    }
137→
138→    private void createInputArea(Composite parent) {
139→        Composite inputArea = new Composite(parent, SWT.NONE);
140→        inputArea.setLayout(new GridLayout(2, false));
141→
142→        // Input text field
143→        inputText = new Text(inputArea, SWT.MULTI | SWT.WRAP | SWT.V_SCROLL | SWT.BORDER);
144→        GridData inputData = new GridData(SWT.FILL, SWT.FILL, true, true);
145→        inputText.setLayoutData(inputData);
146→        inputText.setMessage("Type your message here... (Enter to send, Shift+Enter for new line)");
147→
148→        // Keyboard: Enter sends, Shift+Enter is newline
149→        inputText.addKeyListener(new KeyAdapter() {
150→            @Override
151→            public void keyPressed(KeyEvent e) {
152→                if (e.keyCode == SWT.CR && (e.stateMask & SWT.SHIFT) == 0) {
153→                    e.doit = false;
154→                    sendMessage();
155→                }
156→            }
157→        });
158→
159→        // Buttons panel
160→        Composite buttons = new Composite(inputArea, SWT.NONE);
161→        buttons.setLayout(new GridLayout(1, false));
162→        buttons.setLayoutData(new GridData(SWT.RIGHT, SWT.FILL, false, true));
163→
164→        sendButton = new Button(buttons, SWT.PUSH);
165→        sendButton.setText("Send");
166→        sendButton.setLayoutData(new GridData(SWT.FILL, SWT.TOP, true, false));
167→        sendButton.addSelectionListener(new SelectionAdapter() {
168→            @Override
169→            public void widgetSelected(SelectionEvent e) {
170→                sendMessage();
171→            }
172→        });
173→    }
174→
175→    /**
176→     * Send the current input message to Claude.
177→     */
178→    private void sendMessage() {
179→        if (isLoading) return;
180→        String message = inputText.getText().trim();
181→        if (message.isEmpty()) return;
182→
183→        inputText.setText("");
184→        appendMessage("You", message, true);
185→        setLoading(true);
186→
187→        // Run API call in background thread
188→        Thread thread = new Thread(() -> {
189→            try {
190→                String response = apiClient.chat(message);
191→                Display.getDefault().asyncExec(() -> {
192→                    appendMessage("Claude", response, false);
193→                    setLoading(false);
194→                });
195→            } catch (Exception ex) {
196→                Display.getDefault().asyncExec(() -> {
197→                    appendMessage("Error", ex.getMessage(), false);
198→                    setLoading(false);
199→                });
200→            }
201→        });
202→        thread.setDaemon(true);
203→        thread.start();
204→    }
205→
206→    /**
207→     * Public method to send code directly from handlers.
208→     */
209→    public void sendCode(String prompt, String code) {
210→        String fullMessage = prompt + "\n\n```\n" + code + "\n```";
211→        inputText.setText(fullMessage);
212→        sendMessage();
213→    }
214→
215→    private void appendMessage(String sender, String message, boolean isUser) {
216→        if (chatDisplay.isDisposed()) return;
217→
218→        String separator = chatDisplay.getText().isEmpty() ? "" : "\n\n";
219→        String header = sender + ":\n";
220→        String content = message + "\n";
221→
222→        int startPos = chatDisplay.getText().length();
223→        chatDisplay.append(separator + header + content);
224→
225→        // Style the header
226→        int headerStart = startPos + separator.length();
227→        org.eclipse.swt.custom.StyleRange headerStyle = new org.eclipse.swt.custom.StyleRange();
228→        headerStyle.start = headerStart;
229→        headerStyle.length = header.length();
230→        headerStyle.fontStyle = SWT.BOLD;
231→        headerStyle.foreground = isUser ? userTextColor : claudeTextColor;
232→        chatDisplay.setStyleRange(headerStyle);
233→
234→        // Scroll to bottom
235→        chatDisplay.setTopIndex(chatDisplay.getLineCount() - 1);
236→    }
237→
238→    private void setLoading(boolean loading) {
239→        isLoading = loading;
240→        sendButton.setEnabled(!loading);
241→        inputText.setEnabled(!loading);
242→        statusLabel.setText(loading ? "Claude is thinking..." : "Ready.");
243→    }
244→
245→    @Override
246→    public void setFocus() {
247→        inputText.setFocus();
248→    }
249→
250→    @Override
251→    public void dispose() {
252→        super.dispose();
253→    }
254→}
