  1→package com.anthropic.eclipse.claude.api;
  2→
  3→import java.io.*;
  4→import java.net.HttpURLConnection;
  5→import java.net.URI;
  6→import java.nio.charset.StandardCharsets;
  7→import java.util.ArrayList;
  8→import java.util.List;
  9→import org.eclipse.jface.preference.IPreferenceStore;
 10→import com.anthropic.eclipse.claude.Activator;
 11→import com.anthropic.eclipse.claude.preferences.PreferenceConstants;
 12→import com.anthropic.eclipse.claude.preferences.SecureApiKeyStore;
 13→import com.anthropic.eclipse.claude.util.JsonParser;
 14→
 15→/**
 16→ * Client for communicating with the Anthropic Claude API.
 17→ */
 18→public class ClaudeApiClient {
 19→
 20→    private static final String API_URL = "https://api.anthropic.com/v1/messages";
 21→    private static final String ANTHROPIC_VERSION = "2023-06-01";
 22→
 23→    // Conversation history for multi-turn chat
 24→    private List<Message> conversationHistory = new ArrayList<>();
 25→
 26→    public static class Message {
 27→        public final String role;
 28→        public final String content;
 29→
 30→        public Message(String role, String content) {
 31→            this.role = role;
 32→            this.content = content;
 33→        }
 34→    }
 35→
 36→    /**
 37→     * Send a message and get a response. Maintains conversation history.
 38→     */
 39→    public String chat(String userMessage) throws Exception {
 40→        conversationHistory.add(new Message("user", userMessage));
 41→        String response = callApi(conversationHistory);
 42→        conversationHistory.add(new Message("assistant", response));
 43→        return response;
 44→    }
 45→
 46→    /**
 47→     * Send a one-shot message without maintaining history.
 48→     */
 49→    public String sendOneShot(String systemPrompt, String userMessage) throws Exception {
 50→        List<Message> messages = new ArrayList<>();
 51→        messages.add(new Message("user", userMessage));
 52→        return callApi(systemPrompt, messages);
 53→    }
 54→
 55→    /**
 56→     * Clear conversation history.
 57→     */
 58→    public void clearHistory() {
 59→        conversationHistory.clear();
 60→    }
 61→
 62→    public List<Message> getHistory() {
 63→        return new ArrayList<>(conversationHistory);
 64→    }
 65→
 66→    private String callApi(List<Message> messages) throws Exception {
 67→        return callApi(null, messages);
 68→    }
 69→
 70→    private String callApi(String systemPrompt, List<Message> messages) throws Exception {
 71→        IPreferenceStore prefs = Activator.getDefault().getPreferenceStore();
 72→        String apiKey = SecureApiKeyStore.getApiKey();
 73→        String model = prefs.getString(PreferenceConstants.MODEL);
 74→        int maxTokens = prefs.getInt(PreferenceConstants.MAX_TOKENS);
 75→
 76→        if (apiKey == null || apiKey.trim().isEmpty()) {
 77→            throw new Exception("API Key not configured. Please set your Anthropic API key in Window > Preferences > Claude AI.");
 78→        }
 79→
 80→        // Build JSON payload
 81→        StringBuilder json = new StringBuilder();
 82→        json.append("{");
 83→        json.append("\"model\":\"").append(JsonParser.escapeJsonString(model)).append("\",");
 84→        json.append("\"max_tokens\":").append(maxTokens).append(",");
 85→
 86→        if (systemPrompt != null && !systemPrompt.isEmpty()) {
 87→            json.append("\"system\":\"").append(JsonParser.escapeJsonString(systemPrompt)).append("\",");
 88→        }
 89→
 90→        json.append("\"messages\":[");
 91→        for (int i = 0; i < messages.size(); i++) {
 92→            Message msg = messages.get(i);
 93→            json.append("{\"role\":\"").append(msg.role).append("\",");
 94→            json.append("\"content\":\"").append(JsonParser.escapeJsonString(msg.content)).append("\"}");
 95→            if (i < messages.size() - 1) json.append(",");
 96→        }
 97→        json.append("]}");
 98→
 99→        // Make HTTP request
100→        HttpURLConnection conn = (HttpURLConnection) URI.create(API_URL).toURL().openConnection();
101→        try {
102→            conn.setRequestMethod("POST");
103→            conn.setRequestProperty("Content-Type", "application/json");
104→            conn.setRequestProperty("x-api-key", apiKey);
105→            conn.setRequestProperty("anthropic-version", ANTHROPIC_VERSION);
106→            conn.setDoOutput(true);
107→            conn.setConnectTimeout(30000);
108→            conn.setReadTimeout(120000);
109→
110→            try (OutputStream os = conn.getOutputStream()) {
111→                byte[] input = json.toString().getBytes(StandardCharsets.UTF_8);
112→                os.write(input, 0, input.length);
113→            }
114→
115→            int responseCode = conn.getResponseCode();
116→            InputStream is = responseCode >= 400 ? conn.getErrorStream() : conn.getInputStream();
117→
118→            StringBuilder response = new StringBuilder();
119→            try (BufferedReader br = new BufferedReader(new InputStreamReader(is, StandardCharsets.UTF_8))) {
120→                String line;
121→                while ((line = br.readLine()) != null) {
122→                    response.append(line);
123→                }
124→            }
125→
126→            if (responseCode >= 400) {
127→                throw new Exception("API Error (" + responseCode + "): " + response.toString());
128→            }
129→
130→            return extractTextFromResponse(response.toString());
131→        } finally {
132→            conn.disconnect();
133→        }
134→    }
135→
136→    /**
137→     * Simple JSON text extraction - parses the "text" field from Claude's response.
138→     */
139→    private String extractTextFromResponse(String jsonResponse) {
140→        // Look for "text":"..." in the content array
141→        String marker = "\"text\":\"";
142→        int start = jsonResponse.indexOf(marker);
143→        if (start == -1) {
144→            // Try to extract error message
145→            marker = "\"message\":\"";
146→            start = jsonResponse.indexOf(marker);
147→            if (start == -1) return "Could not parse response: " + jsonResponse;
148→        }
149→
150→        start += marker.length();
151→        StringBuilder result = new StringBuilder();
152→        boolean escape = false;
153→
154→        for (int i = start; i < jsonResponse.length(); i++) {
155→            char c = jsonResponse.charAt(i);
156→            if (escape) {
157→                switch (c) {
158→                    case '"': result.append('"'); break;
159→                    case '\\': result.append('\\'); break;
160→                    case '/': result.append('/'); break;
161→                    case 'n': result.append('\n'); break;
162→                    case 'r': result.append('\r'); break;
163→                    case 't': result.append('\t'); break;
164→                    default: result.append('\\').append(c);
165→                }
166→                escape = false;
167→            } else if (c == '\\') {
168→                escape = true;
169→            } else if (c == '"') {
170→                break;
171→            } else {
172→                result.append(c);
173→            }
174→        }
175→
176→        return result.toString();
177→    }
178→
179→}
