 12→/**
 13→ * Central conversation model that bridges the CLI protocol handler and the UI.
 14→ * Implements ICliMessageListener to receive messages from the CLI process,
 15→ * and notifies IConversationListeners (typically the UI view) of changes.
 16→ *
 17→ * Maintains the complete conversation state in memory including all messages,
 18→ * tool calls, and usage information.
 19→ *
 20→ * Thread safety: onMessage() is called from the NDJSON reader thread while
 21→ * getMessages(), isStreaming(), etc. may be called from the UI thread.
 22→ * All access to mutable state is synchronized on {@code this}.
 23→ */
 24→public class ConversationModel implements ICliMessageListener {
 25→
 26→    private final List<MessageBlock> messages = new ArrayList<>();
 27→    private final List<IConversationListener> listeners = new CopyOnWriteArrayList<>();
 28→    private volatile SessionInfo sessionInfo;
 29→    private final UsageInfo cumulativeUsage = new UsageInfo();
 30→
 31→    // Streaming state
 32→    private volatile MessageBlock currentStreamingBlock;
 33→    private final Map<Integer, MessageBlock.ToolCallSegment> activeToolCalls = new ConcurrentHashMap<>();
 34→    /**
 35→     * True while stream events (message_start, content_block_start/delta/stop, message_stop)
 36→     * are driving the current assistant response. Reset to false by handleResult().
 37→     *
 38→     * When true, all "assistant" NDJSON messages are treated as redundant snapshots sent by
 39→     * --include-partial-messages and are ignored. The stream events are authoritative.
 40→     */
 41→    private volatile boolean usingStreamEvents = false;
 42→
 43→    // ==================== ICliMessageListener Implementation ====================
 44→
 45→    @Override
 46→    public void onMessage(CliMessage message) {
 47→        if (message instanceof CliMessage.SystemInit) {
 48→            handleSystemInit((CliMessage.SystemInit) message);
 49→        } else if (message instanceof CliMessage.AssistantMessage) {
 50→            handleAssistantMessage((CliMessage.AssistantMessage) message);
 51→        } else if (message instanceof CliMessage.UserMessage) {
 52→            handleUserMessage((CliMessage.UserMessage) message);
 53→        } else if (message instanceof CliMessage.StreamEvent) {
 54→            handleStreamEvent((CliMessage.StreamEvent) message);
 55→        } else if (message instanceof CliMessage.ResultMessage) {
 56→            handleResult((CliMessage.ResultMessage) message);
 57→        } else if (message instanceof CliMessage.PermissionRequest) {
 58→            handlePermissionRequest((CliMessage.PermissionRequest) message);
 59→        }
 60→    }
 61→
 62→    @Override
 63→    public void onParseError(String rawLine, Exception error) {
 64→        Activator.logError("[ConversationModel] Parse error: " + error.getMessage() + " - Line: " + rawLine, error);
 65→    }
 66→
 67→    @Override
 68→    public void onConnectionError(IOException error) {
 69→        markActiveToolCallsFailed("Connection lost");
 70→        fireError("Connection to Claude CLI lost: " + error.getMessage());
 71→    }
 72→
 73→    /**
 74→     * Mark all currently-RUNNING tool calls as FAILED.
 75→     * Called when the CLI stream closes unexpectedly (connection error, process crash, timeout).
 76→     * This prevents tool call widgets from staying in "Running..." forever.
 77→     */
 78→    public void markActiveToolCallsFailed(String reason) {
 79→        for (Map.Entry<Integer, MessageBlock.ToolCallSegment> entry : activeToolCalls.entrySet()) {
 80→            MessageBlock.ToolCallSegment seg = entry.getValue();
 81→            if (seg.getStatus() == MessageBlock.ToolStatus.RUNNING) {
 82→                seg.setStatus(MessageBlock.ToolStatus.FAILED);
 83→                seg.setOutput("⚠ " + reason);
 84→                // Find the parent block and fire toolCallCompleted so UI updates
 85→                List<MessageBlock> snapshot;
 86→                synchronized (messages) { snapshot = new ArrayList<>(messages); }
 87→                for (MessageBlock block : snapshot) {
 88→                    if (block.findToolCall(seg.getToolId()) != null) {
 89→                        fireToolCallCompleted(block, seg);
 90→                        break;
 91→                    }
 92→                }
 93→            }
 94→        }
 95→        activeToolCalls.clear();
 96→    }
 97→
 98→    /**
 99→     * Returns true if any tool call is currently in RUNNING state.
100→     * Used by the streaming timeout check to avoid false timeouts during
101→     * long-running tool executions (e.g. a slow Maven build).
102→     */
103→    public boolean hasRunningToolCalls() {
104→        for (MessageBlock.ToolCallSegment seg : activeToolCalls.values()) {
105→            if (seg.getStatus() == MessageBlock.ToolStatus.RUNNING) return true;
106→        }
107→        return false;
108→    }
