110→    // ==================== Public API ====================
111→
112→    /**
113→     * Add a user message to the conversation (before sending to CLI).
114→     */
115→    public void addUserMessage(String content) {
116→        MessageBlock block = new MessageBlock(MessageBlock.Role.USER);
117→        MessageBlock.TextSegment textSeg = new MessageBlock.TextSegment();
