125→
126→    /**
127→     * Get all messages in the conversation (snapshot copy for thread safety).
128→     */
129→    public List<MessageBlock> getMessages() {
130→        synchronized (messages) {
131→            return Collections.unmodifiableList(new ArrayList<>(messages));
132→        }
133→    }
134→
135→    /**
136→     * Get the current session info.
137→     */
138→    public SessionInfo getSessionInfo() {
139→        return sessionInfo;
140→    }
141→
142→    /**
143→     * Get cumulative usage information.
144→     */
145→    public UsageInfo getCumulativeUsage() {
146→        return cumulativeUsage;
147→    }
148→
149→    /**
150→     * Get the currently streaming assistant block (may have partial content).
151→     */
152→    public MessageBlock getCurrentStreamingBlock() {
