177→    /**
178→     * Load historical messages into the model and replay them as UI events.
179→     * Used when resuming a session to pre-populate the chat with past messages.
180→     * Fires onUserMessageAdded / onAssistantMessageStarted+Completed for each block
181→     * so the view builds corresponding widgets.
182→     *
183→     * Must be called on a fresh (empty) model — does NOT clear existing messages first.
184→     */
185→    public void loadHistory(List<MessageBlock> historicalBlocks) {
186→        synchronized (messages) {
187→            messages.addAll(historicalBlocks);
188→        }
189→        for (MessageBlock block : historicalBlocks) {
190→            if (block.getRole() == MessageBlock.Role.USER) {
191→                fireUserMessageAdded(block);
192→            } else if (block.getRole() == MessageBlock.Role.ASSISTANT) {
193→                fireAssistantMessageStarted(block);
194→                fireAssistantMessageCompleted(block);
195→            }
196→        }
197→    }
198→
199→    /**
200→     * Get message count.
201→     */
202→    public int getMessageCount() {
203→        synchronized (messages) {
204→            return messages.size();
205→        }
206→    }
207→
208→    // ==================== Listener Management ====================
209→
210→    public void addListener(IConversationListener listener) {
211→        listeners.add(listener);
212→    }
213→
214→    public void removeListener(IConversationListener listener) {
