218→    // ==================== Message Handlers ====================
219→
220→    private void handleSystemInit(CliMessage.SystemInit init) {
221→        sessionInfo = new SessionInfo(init.getSessionId());
222→        sessionInfo.setModel(init.getModel());
223→        sessionInfo.setWorkingDirectory(init.getCwd());
224→        sessionInfo.setPermissionMode(init.getPermissionMode());
225→        fireSessionInitialized(sessionInfo);
