228→    private void handleAssistantMessage(CliMessage.AssistantMessage msg) {
229→        // When stream events are active, ignore ALL assistant messages. The stream events
230→        // (message_start/content_block_*/message_stop) are authoritative and already drive the UI.
231→        if (usingStreamEvents) {
232→            return;
233→        }
234→        // Also ignore if the last message is already ASSISTANT (complete or still streaming).
235→        // The CLI sends redundant assistant snapshots mid-stream and after result.
236→        synchronized (messages) {
237→            if (!messages.isEmpty()) {
238→                MessageBlock lastMsg = messages.get(messages.size() - 1);
239→                if (lastMsg.getRole() == MessageBlock.Role.ASSISTANT) {
240→                    return; // Already have an assistant message — skip duplicate
241→                }
242→            }
243→        }
244→        // Also skip if there's an active streaming block
245→        if (currentStreamingBlock != null) {
246→            return;
247→        }
248→
249→        // If we received a full message directly (non-streaming), create a block for it
250→        if (msg.getContent() != null && !msg.getContent().isEmpty()) {
251→            MessageBlock block = new MessageBlock(MessageBlock.Role.ASSISTANT);
252→            for (CliMessage.ContentBlock contentBlock : msg.getContent()) {
253→                if ("text".equals(contentBlock.getType())) {
254→                    MessageBlock.TextSegment seg = new MessageBlock.TextSegment();
255→                    seg.appendText(contentBlock.getText() != null ? contentBlock.getText() : "");
256→                    block.addSegment(seg);
257→                } else if ("tool_use".equals(contentBlock.getType())) {
258→                    MessageBlock.ToolCallSegment seg = new MessageBlock.ToolCallSegment();
259→                    seg.setToolId(contentBlock.getId());
260→                    seg.setToolName(contentBlock.getName());
261→                    seg.setInput(contentBlock.getInputAsString());
262→                    seg.setStatus(MessageBlock.ToolStatus.COMPLETED);
263→                    block.addSegment(seg);
264→                }
265→            }
266→            synchronized (messages) {
267→                messages.add(block);
268→            }
269→            fireAssistantMessageStarted(block);
270→            fireAssistantMessageCompleted(block);
271→        }
272→    }
