274→    private void handleUserMessage(CliMessage.UserMessage msg) {
275→        // Tool results from the CLI - update the corresponding tool call
276→        if (msg.getContent() != null) {
277→            for (CliMessage.ContentBlock contentBlock : msg.getContent()) {
278→                if ("tool_result".equals(contentBlock.getType())) {
279→                    updateToolCallResult(contentBlock);
280→                }
281→            }
282→        }
283→    }
