285→    private void handleStreamEvent(CliMessage.StreamEvent event) {
286→        String eventType = event.getEventType();
287→        if (eventType == null) return;
288→
289→        switch (eventType) {
290→            case "message_start":
291→                handleMessageStart(event);
292→                break;
293→            case "content_block_start":
294→                handleContentBlockStart(event);
295→                break;
296→            case "content_block_delta":
297→                handleContentBlockDelta(event);
298→                break;
299→            case "content_block_stop":
300→                handleContentBlockStop(event);

300→                handleContentBlockStop(event);
301→                break;
302→            case "message_delta":
303→                handleMessageDelta(event);
304→                break;
305→            case "message_stop":
306→                handleMessageStop(event);
307→                break;
308→        }
309→    }
310→
311→    private void handleMessageStart(CliMessage.StreamEvent event) {
312→        // Start a new assistant message — but don't fire onAssistantMessageStarted yet.
313→        // We defer that until the first content block arrives so we never show an empty bubble.
314→        usingStreamEvents = true; // stream events are now driving this response
315→        currentStreamingBlock = new MessageBlock(MessageBlock.Role.ASSISTANT);
316→        synchronized (messages) {
317→            messages.add(currentStreamingBlock);
318→        }
319→        activeToolCalls.clear();
320→    }
321→
322→    private void handleContentBlockStart(CliMessage.StreamEvent event) {
323→        boolean fireStarted = false;
324→        if (currentStreamingBlock == null) {
325→            // Auto-create streaming block if we missed message_start
326→            usingStreamEvents = true;
327→            currentStreamingBlock = new MessageBlock(MessageBlock.Role.ASSISTANT);
328→            synchronized (messages) {
329→                messages.add(currentStreamingBlock);
330→            }
331→            fireStarted = true;
332→        } else if (currentStreamingBlock.getSegments().isEmpty()) {
333→            // First content on a block that was pre-created by handleMessageStart
334→            fireStarted = true;
335→        }
336→
337→        CliMessage.ContentBlock contentBlock = event.getContentBlock();
338→        if (contentBlock != null) {
339→            if ("thinking".equals(contentBlock.getType())) {
340→                // Extended thinking block — the model is reasoning internally.
341→                // Do NOT add a segment or fire onAssistantMessageStarted yet.
342→                // Just notify the UI so it can update the indicator text.
343→                fireExtendedThinkingStarted();
344→            } else if ("text".equals(contentBlock.getType())) {
345→                // Visible text is starting — the thinking phase (if any) is now over.
346→                fireExtendedThinkingEnded();
347→                // Start a new text segment
348→                currentStreamingBlock.getOrCreateLastTextSegment();
349→                if (fireStarted) fireAssistantMessageStarted(currentStreamingBlock);
350→            } else if ("tool_use".equals(contentBlock.getType())) {
351→                // Start a new tool call segment
352→                MessageBlock.ToolCallSegment toolSeg = new MessageBlock.ToolCallSegment();
353→                toolSeg.setToolId(contentBlock.getId());
354→                toolSeg.setToolName(contentBlock.getName());
355→                toolSeg.setStatus(MessageBlock.ToolStatus.RUNNING);
356→                currentStreamingBlock.addSegment(toolSeg);
357→                activeToolCalls.put(event.getIndex(), toolSeg);
358→                // Fire started before tool call so the composite exists first
359→                if (fireStarted) fireAssistantMessageStarted(currentStreamingBlock);
360→                fireToolCallStarted(currentStreamingBlock, toolSeg);
361→            }
362→        } else if (fireStarted) {
363→            fireAssistantMessageStarted(currentStreamingBlock);
364→        }
365→    }
366→
367→    private void handleContentBlockDelta(CliMessage.StreamEvent event) {
368→        if (currentStreamingBlock == null) return;
369→
370→        CliMessage.Delta delta = event.getDelta();
371→        if (delta == null) return;
372→
373→        if ("text_delta".equals(delta.getType()) && delta.getText() != null) {
374→            // Append text to the current text segment
375→            MessageBlock.TextSegment textSeg = currentStreamingBlock.getOrCreateLastTextSegment();
376→            textSeg.appendText(delta.getText());
377→            fireStreamingTextAppended(currentStreamingBlock, delta.getText());
378→
379→        } else if ("input_json_delta".equals(delta.getType())) {
380→            // Append to tool input
381→            MessageBlock.ToolCallSegment toolSeg = activeToolCalls.get(event.getIndex());
382→            if (toolSeg != null) {
383→                String inputDelta = delta.getPartialJson() != null ? delta.getPartialJson() : delta.getText();
384→                if (inputDelta != null) {
385→                    toolSeg.appendInput(inputDelta);
386→                    fireToolCallInputDelta(currentStreamingBlock, toolSeg, inputDelta);
387→                }
388→            }
389→        }
390→    }
