392→    private void handleContentBlockStop(CliMessage.StreamEvent event) {
393→        // Content block finalized - if it was a tool call, it's now waiting for result
394→        MessageBlock.ToolCallSegment toolSeg = activeToolCalls.get(event.getIndex());
395→        if (toolSeg != null) {
396→            // Tool call input is complete, now waiting for execution/result
397→            toolSeg.setStatus(MessageBlock.ToolStatus.RUNNING);
398→            // Notify listeners: full input is available, BEFORE tool executes.
399→            // This is the right place to snapshot files for revert/diff.
400→            fireToolCallInputComplete(currentStreamingBlock, toolSeg);
401→        }
402→    }
403→
404→    private void handleMessageDelta(CliMessage.StreamEvent event) {
405→        // Message-level update (stop_reason, usage)
406→        CliMessage.Delta delta = event.getDelta();
407→        if (delta != null && delta.getStopReason() != null) {
408→            // The message is finishing with this stop reason
409→        }
410→    }
411→
412→    private void handleMessageStop(CliMessage.StreamEvent event) {
413→        // Message is complete
414→        if (currentStreamingBlock != null) {
415→            fireAssistantMessageCompleted(currentStreamingBlock);
416→            currentStreamingBlock = null;
417→        }
418→    }
419→
420→    private void handleResult(CliMessage.ResultMessage result) {
421→        // NOTE: Do NOT reset usingStreamEvents here. The CLI sends a redundant
422→        // assistant snapshot AFTER the result message. If we reset the flag,
423→        // handleAssistantMessage would process that snapshot and duplicate the text.
424→        // The flag is reset in handleMessageStart when a new streaming turn begins.
425→
426→        // Update usage
427→        cumulativeUsage.addUsage(
428→            result.getInputTokens(),
429→            result.getOutputTokens(),
430→            result.getCostUsd(),
431→            result.getDurationMs(),
432→            result.getNumTurns()
433→        );
434→
435→        // Update session info
436→        if (sessionInfo != null) {
437→            sessionInfo.setSessionId(result.getSessionId());
438→            synchronized (messages) {
439→                sessionInfo.setMessageCount(messages.size());
440→            }
441→            sessionInfo.touch();
442→        }
443→
444→        // If it was an error result, add an error message
445→        if (result.isError() && result.getResult() != null) {
446→            fireError(result.getResult());
447→        }
448→
449→        // Finalize any streaming block
450→        if (currentStreamingBlock != null) {
451→            fireAssistantMessageCompleted(currentStreamingBlock);
452→            currentStreamingBlock = null;
453→        }
454→
455→        fireResultReceived(cumulativeUsage);
456→    }
