458→    private void handlePermissionRequest(CliMessage.PermissionRequest request) {
459→        String toolUseId = request.getToolUseId();
460→        String toolName = request.getToolName() != null ? request.getToolName() : "Unknown tool";
461→        String description = request.getDescription();
462→        if (description == null) {
463→            description = "Claude wants to use: " + toolName;
464→        }
465→        // requestId is non-null for new control_request format, null for old format
466→        String requestId = request.getRequestId();
467→        // toolInput is needed to echo back in control_response as updatedInput (allow path)
468→        Object toolInput = request.getToolInput();
469→        firePermissionRequested(toolUseId, toolName, description, requestId, toolInput);
470→    }
