472→    private void updateToolCallResult(CliMessage.ContentBlock toolResult) {
473→        String toolUseId = toolResult.getToolUseId();
474→        if (toolUseId == null) return;
475→
476→        // Find the matching tool call in recent messages (snapshot for safe iteration)
477→        List<MessageBlock> snapshot;
478→        synchronized (messages) {
479→            snapshot = new ArrayList<>(messages);
480→        }
481→        for (int i = snapshot.size() - 1; i >= 0; i--) {
482→            MessageBlock block = snapshot.get(i);
483→            MessageBlock.ToolCallSegment toolSeg = block.findToolCall(toolUseId);
484→            if (toolSeg != null) {
485→                String content = toolResult.getContent();
486→                toolSeg.setOutput(content);
487→                // Also treat <tool_use_error> in the content as a failure
488→                boolean isFailed = toolResult.isError()
489→                    || (content != null && content.contains("<tool_use_error>"));
490→                toolSeg.setStatus(isFailed ?
491→                    MessageBlock.ToolStatus.FAILED : MessageBlock.ToolStatus.COMPLETED);
492→                fireToolCallCompleted(block, toolSeg);
493→                break;
494→            }
495→        }
496→    }
