 11→/**
 12→ * Handles the NDJSON (Newline-Delimited JSON) protocol for communication
 13→ * with the Claude CLI process in stream-json mode.
 14→ *
 15→ * Reads NDJSON lines from CLI stdout and parses them into CliMessage objects.
 16→ * Writes NDJSON messages to CLI stdin for multi-turn conversation.
 17→ */
 18→public class NdjsonProtocolHandler {
 19→
 20→    private final InputStream stdout;
 21→    private final OutputStream stdin;
 22→    private final InputStream stderr;
 23→
 24→    private final List<ICliMessageListener> listeners = new CopyOnWriteArrayList<>();
 25→    private volatile boolean running = false;
 26→    private Thread readerThread;
 27→    private Thread errorThread;
 28→
 29→    public NdjsonProtocolHandler(InputStream stdout, OutputStream stdin, InputStream stderr) {
 30→        this.stdout = stdout;
 31→        this.stdin = stdin;
 32→        this.stderr = stderr;
 33→    }
 34→
 35→    /**
 36→     * Start background threads reading from stdout and stderr.
 37→     */
 38→    public void startReading() {
 39→        running = true;
 40→
 41→        readerThread = new Thread(this::readLoop, "Claude-CLI-NDJSON-Reader");
 42→        readerThread.setDaemon(true);
 43→        readerThread.start();
 44→
 45→        errorThread = new Thread(this::errorLoop, "Claude-CLI-Error-Reader");
 46→        errorThread.setDaemon(true);
 47→        errorThread.start();
 48→    }
 49→
 50→    /**
 51→     * Write a user message to stdin as NDJSON.
 52→     */
 53→    public synchronized void writeMessage(String userContent) {
 54→        String json = CliMessage.createUserInputJson(userContent);
 55→        writeRawNdjson(json);
 56→    }
 57→
 58→    /**
 59→     * Write a raw NDJSON line to stdin.
 60→     */
 61→    public synchronized void writeRawNdjson(String jsonLine) {
 62→        try {
 63→            byte[] bytes = (jsonLine + "\n").getBytes(StandardCharsets.UTF_8);
 64→            stdin.write(bytes);
 65→            stdin.flush();
 66→        } catch (IOException e) {
 67→            for (ICliMessageListener listener : listeners) {
 68→                listener.onConnectionError(e);
 69→            }
 70→        }
 71→    }
 72→
 73→    /**
 74→     * Stop reading threads.
 75→     */
 76→    public void stop() {
 77→        running = false;
 78→        if (readerThread != null) {
 79→            readerThread.interrupt();
 80→        }
 81→        if (errorThread != null) {
 82→            errorThread.interrupt();
 83→        }
 84→    }
 85→
 86→    /**
 87→     * Add a listener for parsed messages.
 88→     */
 89→    public void addListener(ICliMessageListener listener) {
 90→        listeners.add(listener);
 91→    }
 92→
 93→    /**
 94→     * Remove a listener.
 95→     */
 96→    public void removeListener(ICliMessageListener listener) {
 97→        listeners.remove(listener);
 98→    }
 99→
100→    // ==================== Internal Read Loops ====================
101→
102→    private void readLoop() {
103→        try (BufferedReader reader = new BufferedReader(
104→                new InputStreamReader(stdout, StandardCharsets.UTF_8))) {
105→            String line;
106→            while (running && (line = reader.readLine()) != null) {
107→                line = line.trim();
108→                if (line.isEmpty()) continue;
109→                try {
110→                    CliMessage message = parseLine(line);
111→                    if (message != null) {
112→                        for (ICliMessageListener listener : listeners) {
113→                            listener.onMessage(message);
114→                        }
115→                    }
116→                } catch (Exception e) {
117→                    for (ICliMessageListener listener : listeners) {
118→                        listener.onParseError(line, e);
119→                    }
120→                }
121→            }
122→        } catch (IOException e) {
123→            if (running) {
124→                for (ICliMessageListener listener : listeners) {
125→                    listener.onConnectionError(e);
126→                }
127→            }
128→        }
129→    }
130→
131→    private void errorLoop() {
132→        try (BufferedReader reader = new BufferedReader(
133→                new InputStreamReader(stderr, StandardCharsets.UTF_8))) {
134→            String line;
135→            while (running && (line = reader.readLine()) != null) {
136→                // Log stderr to System.err for debugging
137→                Activator.logInfo("[Claude CLI stderr] " + line);
138→            }
139→        } catch (IOException e) {
140→            // stderr closed - normal during shutdown
141→        }
142→    }
143→
144→    // ==================== NDJSON Parsing ====================
145→
146→    /**
147→     * Parse a single NDJSON line into the appropriate CliMessage subclass.
148→     */
149→    CliMessage parseLine(String jsonLine) {
150→        Map<String, Object> json = JsonParser.parseObject(jsonLine);
151→        String type = JsonParser.getString(json, "type");
152→        if (type == null) return null;
153→
154→        switch (type) {
155→            case "system":
156→                return parseSystemInit(json);
157→            case "assistant":
158→                return parseAssistantMessage(json);
159→            case "user":
160→                return parseUserMessage(json);
161→            case "result":
162→                return parseResultMessage(json);
163→            case "stream_event":
164→                return parseStreamEvent(json);
165→            case "tool_use_permission":
166→            case "permission_request":
167→            case "tool_permission":
168→                return parsePermissionRequest(json, type);
169→            case "control_request":
170→                // New CLI format for permission prompts (can_use_tool subtype)
171→                return parseControlRequest(json);
172→            case "rate_limit_event":
173→                // Informational event about API rate limits — no action needed by the plugin
174→                Activator.logInfo("[NDJSON] rate_limit_event: status="
175→                    + JsonParser.getString(JsonParser.getMap(json, "rate_limit_info"), "status")
176→                    + " overageStatus="
177→                    + JsonParser.getString(JsonParser.getMap(json, "rate_limit_info"), "overageStatus"));
178→                return null;
179→            case "tool_use_summary":
180→                // Informational summary of a completed tool use — no action needed
181→                return null;
182→            default:
183→                // Log unknown message types for debugging
184→                Activator.logWarning("[NDJSON] Unknown message type: " + type
185→                    + " - raw: " + jsonLine.substring(0, Math.min(200, jsonLine.length())));
186→                // Check if this might be a permission-related message
187→                if (type.contains("permission") || type.contains("Permission")) {
188→                    return parsePermissionRequest(json, type);
189→                }
190→                return null;
191→        }
192→    }
193→
194→    private CliMessage.SystemInit parseSystemInit(Map<String, Object> json) {
195→        CliMessage.SystemInit msg = new CliMessage.SystemInit();
196→        msg.setSubtype(JsonParser.getString(json, "subtype"));
197→        msg.setSessionId(JsonParser.getString(json, "session_id"));
198→        msg.setModel(JsonParser.getString(json, "model"));
199→        msg.setCwd(JsonParser.getString(json, "cwd"));
200→        msg.setPermissionMode(JsonParser.getString(json, "permission_mode"));

