 20→/**
 21→ * Renders a single message (user or assistant turn) as a composite widget.
 22→ * Contains: role label, content area (streaming text + tool calls + code blocks).
 23→ */
 24→public class MessageComposite extends Composite {
 25→
 26→    private final MessageBlock messageBlock;
 27→    private Composite contentArea;
 28→    private StreamingTextWidget currentTextWidget;
 29→    private final List<ToolCallComposite> toolCallWidgets = new ArrayList<>();
 30→    private final List<CodeBlockComposite> codeBlockWidgets = new ArrayList<>();
