 54→    private void initColors() {
 55→        ThemeManager tm = ThemeManager.getInstance();
 56→        userBgColor = tm.getColor(tm.userMessageBg);
 57→        assistantBgColor = tm.getColor(tm.assistantMessageBg);
 58→        errorBgColor = tm.getColor(tm.errorMessageBg);
 59→        systemBgColor = tm.getColor(tm.systemMessageBg);
