 63→    private void createUI() {
 64→        GridLayout layout = new GridLayout(1, false);
 65→        layout.marginWidth = 12;
 66→        layout.marginHeight = 8;
 67→        layout.verticalSpacing = 6;
 68→        setLayout(layout);
 69→        setLayoutData(new GridData(SWT.FILL, SWT.TOP, true, false));
 70→
 71→        // Set background based on role
 72→        switch (messageBlock.getRole()) {
 73→            case USER:
 74→                setBackground(userBgColor);
 75→                break;
 76→            case ERROR:
 77→                setBackground(errorBgColor);
 78→                break;
 79→            case SYSTEM:
 80→                setBackground(systemBgColor);
 81→                break;
 82→            default:
 83→                setBackground(assistantBgColor);
 84→                break;
 85→        }
 86→
 87→        // Role header
 88→        createRoleHeader();
 89→
 90→        // Content area
 91→        contentArea = new Composite(this, SWT.NONE);
 92→        GridLayout contentLayout = new GridLayout(1, false);
 93→        contentLayout.marginWidth = 0;
 94→        contentLayout.marginHeight = 0;
 95→        contentLayout.verticalSpacing = 4;
 96→        contentArea.setLayout(contentLayout);
 97→        contentArea.setLayoutData(new GridData(SWT.FILL, SWT.TOP, true, false));
 98→        contentArea.setBackground(getBackground());
 99→
100→        // If the message already has content (non-streaming), render it.
101→        // Skip for ASSISTANT messages that are still being streamed — the streaming
102→        // path (appendStreamingText) will handle those. Rendering here AND streaming
103→        // would duplicate the first few tokens (e.g., "HiHi!" instead of "Hi!").
104→        if (messageBlock.getRole() != MessageBlock.Role.ASSISTANT || messageBlock.isComplete()) {
105→            renderExistingContent();
106→        }
107→
108→        // Context menu with Fork option
109→        createContextMenu();
110→
111→        addDisposeListener(e -> {
112→            userBgColor.dispose();
113→            assistantBgColor.dispose();
114→            errorBgColor.dispose();
115→            systemBgColor.dispose();
116→            roleColor.dispose();
117→        });
