185→    private void renderExistingContent() {
186→        for (MessageBlock.ContentSegment seg : messageBlock.getSegments()) {
187→            if (seg instanceof MessageBlock.TextSegment) {
188→                MessageBlock.TextSegment textSeg = (MessageBlock.TextSegment) seg;
189→                if (textSeg.getLength() > 0) {
190→                    ensureTextWidget();
191→                    currentTextWidget.appendText(textSeg.getText());
192→                    hasStreamedText = true; // Prevent finalizeContent() from re-adding this text
193→                }
194→            } else if (seg instanceof MessageBlock.ToolCallSegment) {
195→                addToolCallWidget((MessageBlock.ToolCallSegment) seg);
196→            }
197→        }
198→    }
