210→    /**
211→     * Add a tool call collapsible section.
212→     */
213→    public ToolCallComposite addToolCallWidget(ToolCallSegment toolCall) {
214→        if (isDisposed()) return null;
215→        // Close current text widget if any (tool calls appear between text)
216→        if (currentTextWidget != null && !currentTextWidget.isFinalized()) {
217→            finalizeAndExtractCodeBlocks(currentTextWidget);
218→            currentTextWidget = null;
219→        }
220→        ToolCallComposite tcWidget = new ToolCallComposite(contentArea, toolCall);
221→        tcWidget.setBackground(getBackground());
222→        toolCallWidgets.add(tcWidget);
223→        // Propagate context menu to new widget
224→        Menu menu = getMenu();
225→        if (menu != null) {
226→            applyMenuToChildren(tcWidget, menu);
227→            tcWidget.setMenu(menu);
228→        }
229→        relayoutParent();
230→        return tcWidget;
231→    }
