233→    /**
234→     * Update a tool call's status and output in its widget.
235→     */
236→    public void updateToolCall(ToolCallSegment toolCall) {
237→        for (ToolCallComposite tc : toolCallWidgets) {
238→            if (tc.getToolCall() == toolCall) {
239→                tc.setStatus(toolCall.getStatus());
240→                if (toolCall.getOutput() != null) {
241→                    tc.setOutput(toolCall.getOutput());
242→                }
243→                relayoutParent();
244→                break;
245→            }
246→        }
247→    }
