249→    /**
250→     * Returns true if this composite contains a widget for the given tool call segment.
251→     */
252→    public boolean hasToolCall(ToolCallSegment toolCall) {
253→        for (ToolCallComposite tc : toolCallWidgets) {
254→            if (tc.getToolCall() == toolCall) return true;
255→        }
256→        return false;
257→    }
