259→    /**
260→     * Find the ToolCallComposite for the given segment (by reference equality).
261→     */
262→    public ToolCallComposite findToolCallWidget(ToolCallSegment toolCall) {
263→        for (ToolCallComposite tc : toolCallWidgets) {
264→            if (tc.getToolCall() == toolCall) return tc;
265→        }
266→        return null;
267→    }
