269→    /**
270→     * Force-sync every tool call widget's displayed status with its model status.
271→     * Safety net for race conditions between asyncExec items.
272→     */
273→    public void syncToolCallStatuses() {
274→        for (ToolCallComposite tc : toolCallWidgets) {
275→            if (tc.isDisposed()) continue;
276→            ToolCallSegment seg = tc.getToolCall();
277→            tc.setStatus(seg.getStatus());
278→            if (seg.getOutput() != null) {
279→                tc.setOutput(seg.getOutput());
280→            }
281→        }
282→    }
