284→    /**
285→     * Finalize: parse accumulated text for markdown, extract code blocks.
286→     * If streaming was disabled (text widget is empty but MessageBlock has content),
287→     * populate from the MessageBlock first.
288→     */
289→    public void finalizeContent() {
290→        if (finalized) return; // Prevent double finalization
291→        finalized = true;
292→
293→        // If streaming was disabled, the text widget may be empty or not exist.
294→        // Populate it from the MessageBlock's accumulated text.
295→        // BUT: if text was already rendered during streaming (hasStreamedText),
296→        // do NOT re-populate — the text is already in the UI widgets.
297→        if (!hasStreamedText) {
298→            String fullText = messageBlock.getFullText();
299→            if (fullText != null && !fullText.isEmpty()) {
300→                if (currentTextWidget == null || currentTextWidget.isFinalized()) {
301→                    if (currentTextWidget == null || currentTextWidget.getRawText().isEmpty()) {
302→                        ensureTextWidget();
303→                        currentTextWidget.appendText(fullText);
304→                    }
305→                } else if (currentTextWidget.getRawText().isEmpty()) {
306→                    currentTextWidget.appendText(fullText);
307→                }
308→            }
309→        }
310→
311→        if (currentTextWidget != null && !currentTextWidget.isFinalized()) {
312→            finalizeAndExtractCodeBlocks(currentTextWidget);
313→        }
314→        relayoutParent();
315→    }
