317→    /**
318→     * Finalize a StreamingTextWidget: apply markdown rendering (which removes code
319→     * block content from the display) and create CodeBlockComposite widgets for
320→     * each fenced code block found in the raw text.
321→     */
322→    private void finalizeAndExtractCodeBlocks(StreamingTextWidget widget) {
323→        String rawText = widget.getRawText();
324→        widget.finalizeContent();
325→
326→        // Extract code blocks and create CodeBlockComposite widgets
327→        List<MarkdownRenderer.CodeBlockInfo> codeBlocks =
328→            MarkdownRenderer.extractCodeBlocks(rawText);
329→
330→        for (MarkdownRenderer.CodeBlockInfo blockInfo : codeBlocks) {
331→            CodeBlockComposite cbWidget = new CodeBlockComposite(
332→                contentArea, blockInfo.language, blockInfo.code);
333→            codeBlockWidgets.add(cbWidget);
334→        }
335→    }
