  7→import org.eclipse.swt.custom.StyleRange;
  8→import org.eclipse.swt.custom.StyledText;
  9→import org.eclipse.swt.graphics.Color;
 10→import org.eclipse.swt.widgets.Display;
 11→
 12→/**
 13→ * Converts markdown text into SWT StyleRanges for StyledText widgets.
 14→ * Uses a line-by-line state machine approach - not a full markdown parser.
 15→ *
 16→ * Supports: # headers, **bold**, *italic*, `inline code`, ```code blocks```,
 17→ * - bullet lists, 1. numbered lists.
 18→ *
 19→ * Properly strips markdown delimiters from rendered text and caches Color
 20→ * objects to avoid SWT resource leaks.
 21→ */
 22→public class MarkdownRenderer {
 23→
 24→    /**
 25→     * Info about a code block found in the markdown text.
 26→     */
 27→    public static class CodeBlockInfo {
 28→        public final int startOffset;
 29→        public final int endOffset;
 30→        public final String language;
 31→        public final String code;
 32→
 33→        public CodeBlockInfo(int startOffset, int endOffset, String language, String code) {
 34→            this.startOffset = startOffset;
 35→            this.endOffset = endOffset;
 36→            this.language = language;
 37→            this.code = code;
 38→        }
 39→    }
 40→
 41→    /**
 42→     * Allocate a theme-aware Color. These colors are created fresh per render call
 43→     * and tracked via the provided list so the widget can dispose them when it is destroyed.
 44→     *
 45→     * Using ThemeManager.isDarkMode() keeps colors correct for both light and dark Eclipse themes.
 46→     */
 47→    private static Color getHeaderColor(Display display) {
 48→        boolean dark = ThemeManager.isDarkMode(display);
 49→        // Light blue accent for headers — visible on both dark and light backgrounds.
 50→        return new Color(display, dark ? new org.eclipse.swt.graphics.RGB(100, 175, 255)
 51→                                       : new org.eclipse.swt.graphics.RGB(20, 80, 170));
 52→    }
 53→
 54→    private static Color getCodeFg(Display display) {
 55→        boolean dark = ThemeManager.isDarkMode(display);
 56→        // Warm amber for inline code text (like VS Code's string color).
 57→        return new Color(display, dark ? new org.eclipse.swt.graphics.RGB(220, 160, 80)
 58→                                       : new org.eclipse.swt.graphics.RGB(170, 50, 20));
 59→    }
 60→
 61→    private static Color getCodeBg(Display display) {
 62→        boolean dark = ThemeManager.isDarkMode(display);
 63→        // Subtle tinted background for inline code.
 64→        return new Color(display, dark ? new org.eclipse.swt.graphics.RGB(48, 48, 54)
 65→                                       : new org.eclipse.swt.graphics.RGB(232, 232, 238));
 66→    }
 67→
 68→    /**
 69→     * Result of processing inline markdown on a single line.
 70→     * Contains the cleaned text (delimiters removed) and style ranges.
 71→     */
 72→    private static class InlineResult {
 73→        String cleanText;
 74→        List<StyleRange> styles = new ArrayList<>();
 75→    }
 76→
 77→    /**
 78→     * Apply markdown styling to a StyledText widget.
 79→     * Processes the full text, strips markdown delimiters, and sets StyleRanges.
 80→     */
 81→    public static void render(StyledText widget, String markdown) {
 82→        if (markdown == null || markdown.isEmpty()) return;
 83→
 84→        Display display = widget.getDisplay();
 85→
 86→        // Allocate per-render theme-aware colors ONCE and dispose them via the widget.
 87→        final Color headerColor = getHeaderColor(display);
 88→        final Color codeFg     = getCodeFg(display);
 89→        final Color codeBg     = getCodeBg(display);
 90→        widget.addDisposeListener(e -> {
 91→            if (!headerColor.isDisposed()) headerColor.dispose();
 92→            if (!codeFg.isDisposed())      codeFg.dispose();
 93→            if (!codeBg.isDisposed())      codeBg.dispose();
 94→        });
 95→
 96→        // Process the text to remove markdown syntax and collect style ranges
 97→        StringBuilder processed = new StringBuilder();
 98→        List<StyleRange> styles = new ArrayList<>();
 99→
100→        String[] lines = markdown.split("\n", -1);
101→        boolean inCodeBlock = false;
102→        int currentOffset = 0;
103→
104→        for (int lineIdx = 0; lineIdx < lines.length; lineIdx++) {
105→            String line = lines[lineIdx];
106→            String suffix = (lineIdx < lines.length - 1) ? "\n" : "";
107→
108→            // Check for code block fences.
109→            // Code blocks are rendered as separate CodeBlockComposite widgets by
110→            // MessageComposite.finalizeContent() — we must NOT render them here too
111→            // or they would appear twice (once inline, once as the widget).
112→            // Strip invisible Unicode characters (RTL mark, etc.) for fence detection
113→            String trimmedLine = line.trim().replaceAll("[\\u200F\\u200E\\u200B\\u200C\\u200D\\uFEFF]", "");
114→            if (trimmedLine.startsWith("```")) {
115→                if (!inCodeBlock) {
116→                    // Opening fence: add one blank separator line so surrounding text
117→                    // has a visual gap before the CodeBlockComposite widget below.
118→                    processed.append("\n");
119→                    currentOffset++;
120→                }
121→                inCodeBlock = !inCodeBlock;
122→                continue;
123→            }
124→
125→            if (inCodeBlock) {
126→                // Skip — this content is rendered by CodeBlockComposite, not here.
127→                continue;
128→            }
129→
130→            // Process markdown line
131→            if (line.startsWith("### ")) {
132→                String headerText = line.substring(4) + suffix;
133→                processed.append(headerText);
134→                addHeaderStyle(styles, currentOffset, headerText.length(), headerColor);
135→                currentOffset += headerText.length();
136→            } else if (line.startsWith("## ")) {
137→                String headerText = line.substring(3) + suffix;
138→                processed.append(headerText);
139→                addHeaderStyle(styles, currentOffset, headerText.length(), headerColor);
140→                currentOffset += headerText.length();
141→            } else if (line.startsWith("# ")) {
142→                String headerText = line.substring(2) + suffix;
143→                processed.append(headerText);
144→                addHeaderStyle(styles, currentOffset, headerText.length(), headerColor);
145→                currentOffset += headerText.length();
146→            } else {
147→                // Regular line - process inline markdown, stripping delimiters
148→                InlineResult result = processInlineMarkdown(line, codeFg, codeBg);
149→                String cleanLine = result.cleanText + suffix;
150→                processed.append(cleanLine);
151→
152→                // Adjust style offsets to the current position in processed text
153→                for (StyleRange sr : result.styles) {
154→                    sr.start += currentOffset;
155→                    styles.add(sr);
156→                }
157→
158→                currentOffset += cleanLine.length();
159→            }
160→        }
161→
162→        // Set the processed text
163→        widget.setText(processed.toString());
164→
165→        // Apply styles
166→        int textLength = processed.length();
167→        for (StyleRange style : styles) {
168→            if (style.start >= 0 && style.start + style.length <= textLength) {
169→                try {
170→                    widget.setStyleRange(style);
171→                } catch (Exception e) {
172→                    // Skip invalid ranges
173→                }
174→            }
175→        }
176→    }
177→
178→    /**
179→     * Process a single line to strip inline markdown delimiters and produce style ranges.
180→     * Handles **bold**, *italic*, and `inline code` - stripping delimiters from output.
181→     * Colors are passed in (already allocated, disposed by the widget's dispose listener).
182→     */
183→    private static InlineResult processInlineMarkdown(String line, Color codeFg, Color codeBg) {
184→        InlineResult result = new InlineResult();
185→        StringBuilder clean = new StringBuilder();
186→        int i = 0;
187→
188→        while (i < line.length()) {
189→            // Check for inline code: `text`
190→            if (line.charAt(i) == '`') {
191→                // Skip triple backtick (code fence inside line - shouldn't happen but be safe)
192→                if (i + 2 < line.length() && line.charAt(i + 1) == '`' && line.charAt(i + 2) == '`') {
193→                    clean.append(line.charAt(i));
194→                    i++;
195→                    continue;
196→                }
197→                int end = line.indexOf('`', i + 1);
198→                if (end > i) {
199→                    String content = line.substring(i + 1, end);
200→                    int start = clean.length();
201→                    clean.append(content);
202→                    StyleRange style = new StyleRange();
203→                    style.start = start;
204→                    style.length = content.length();
205→                    style.foreground = codeFg;
206→                    style.background = codeBg;
207→                    result.styles.add(style);
208→                    i = end + 1;
209→                    continue;
210→                }
211→            }
212→
213→            // Check for bold: **text**
214→            if (i + 1 < line.length() && line.charAt(i) == '*' && line.charAt(i + 1) == '*') {
215→                int end = line.indexOf("**", i + 2);
216→                if (end > i) {
217→                    String content = line.substring(i + 2, end);
218→                    int start = clean.length();
219→                    clean.append(content);
220→                    StyleRange style = new StyleRange();
221→                    style.start = start;
222→                    style.length = content.length();
223→                    style.fontStyle = SWT.BOLD;
224→                    result.styles.add(style);
225→                    i = end + 2;
226→                    continue;
227→                }
228→            }
229→
230→            // Check for italic: *text* (single asterisk, not part of **)
231→            if (line.charAt(i) == '*') {
232→                // Don't match if next char is also * (that's bold)
233→                if (i + 1 < line.length() && line.charAt(i + 1) != '*') {
234→                    int end = line.indexOf('*', i + 1);
235→                    // Make sure closing * is not part of **
236→                    if (end > i && !(end + 1 < line.length() && line.charAt(end + 1) == '*')) {
237→                        String content = line.substring(i + 1, end);
238→                        int start = clean.length();
239→                        clean.append(content);
240→                        StyleRange style = new StyleRange();
241→                        style.start = start;
242→                        style.length = content.length();
243→                        style.fontStyle = SWT.ITALIC;
244→                        result.styles.add(style);
245→                        i = end + 1;
246→                        continue;
247→                    }
248→                }
249→            }
250→
251→            // Regular character
252→            clean.append(line.charAt(i));
253→            i++;
254→        }
255→
256→        result.cleanText = clean.toString();
257→        return result;
258→    }
259→
260→    /**
261→     * Extract code blocks from markdown text.
262→     * Returns list of code block locations and content.
263→     */
264→    public static List<CodeBlockInfo> extractCodeBlocks(String markdown) {
265→        List<CodeBlockInfo> blocks = new ArrayList<>();
266→        if (markdown == null) return blocks;
267→
268→        String[] lines = markdown.split("\n", -1);
269→        boolean inCodeBlock = false;
270→        StringBuilder codeContent = new StringBuilder();
271→        String language = "";
272→        int charOffset = 0;
273→        int blockStartOffset = 0;
274→
275→        for (int i = 0; i < lines.length; i++) {
276→            String line = lines[i];
277→
278→            if (line.trim().startsWith("```") && !inCodeBlock) {
279→                inCodeBlock = true;
280→                language = line.trim().substring(3).trim();
281→                blockStartOffset = charOffset;
282→                codeContent = new StringBuilder();
283→            } else if (line.trim().startsWith("```") && inCodeBlock) {
284→                inCodeBlock = false;
285→                blocks.add(new CodeBlockInfo(
286→                    blockStartOffset,
287→                    charOffset + line.length(),
288→                    language,
289→                    codeContent.toString()
290→                ));
291→            } else if (inCodeBlock) {
292→                if (codeContent.length() > 0) codeContent.append("\n");
293→                codeContent.append(line);
294→            }
295→
296→            charOffset += line.length() + 1; // +1 for newline
297→        }
298→
299→        return blocks;
300→    }

