162→        // If already on the UI thread, run immediately so the change is visible
163→        // before any other asyncExec items run.
164→        if (display.getThread() == Thread.currentThread()) {
165→            updater.run();
166→        } else {
167→            display.asyncExec(updater);
168→        }
169→    }
