209→    private void updateStatusDisplay() {
210→        if (statusLabel == null || statusLabel.isDisposed()) return;
211→
212→        ToolStatus status = toolCall.getStatus();
213→        switch (status) {
214→            case RUNNING:
215→                statusLabel.setText("\u23F3 Running...");  // hourglass
216→                statusLabel.setForeground(runningColor);
217→                break;
218→            case COMPLETED:
219→                statusLabel.setText("\u2713 Done");  // checkmark
220→                statusLabel.setForeground(completedColor);
221→                break;
222→            case FAILED:
223→                statusLabel.setText("\u2717 Failed");  // X mark
224→                statusLabel.setForeground(failedColor);
225→                break;
226→            case NEEDS_PERMISSION:
227→                statusLabel.setText("\u26A0 Permission needed");  // warning
228→                statusLabel.setForeground(runningColor);
229→                break;
230→        }
231→    }
