233→    private void updateDetailsText() {
234→        if (detailsText == null || detailsText.isDisposed()) return;
235→
236→        StringBuilder sb = new StringBuilder();
237→
238→        String input = toolCall.getInput();
239→        if (input != null && !input.isEmpty()) {
240→            sb.append("Input:\n");
241→            // Truncate long inputs for display
242→            if (input.length() > 2000) {
243→                sb.append(input, 0, 2000);
244→                sb.append("\n... (truncated)");
245→            } else {
246→                sb.append(input);
247→            }
248→        }
249→
250→        String output = toolCall.getOutput();
251→        if (output != null && !output.isEmpty()) {
252→            if (sb.length() > 0) sb.append("\n\n");
253→            sb.append("Output:\n");
254→            String displayOutput = stripXmlTags(output);
255→            // Truncate long outputs
256→            if (displayOutput.length() > 3000) {
257→                sb.append(displayOutput, 0, 3000);
258→                sb.append("\n... (truncated)");
259→            } else {
260→                sb.append(displayOutput);
261→            }
262→        }
263→
264→        detailsText.setText(sb.toString());
265→
266→        // Update height
267→        int lineCount = detailsText.getLineCount();
268→        int lineHeight = detailsText.getLineHeight();
269→        int maxHeight = Math.min(lineCount * lineHeight + 10, 300);
270→        GridData gd = (GridData) detailsText.getLayoutData();
271→        gd.heightHint = maxHeight;
272→    }
