274→    /**
275→     * Strip XML wrapper tags from tool output for clean display.
276→     * E.g. "<tool_use_error>message</tool_use_error>" becomes "message".
277→     */
278→    private static String stripXmlTags(String output) {
279→        if (output == null) return "";
280→        String s = output.trim();
281→        // Repeatedly strip a single outer tag pair until none remain
282→        String prev;
283→        do {
284→            prev = s;
285→            // Match an opening tag at the start and its matching closing tag at the end
286→            int open = s.indexOf('<');
287→            if (open != 0) break;
288→            int closeTag = s.indexOf('>');
289→            if (closeTag < 1) break;
290→            String tagName = s.substring(1, closeTag).trim();
291→            // Skip tags with attributes or that look like processed markup
292→            if (tagName.isEmpty() || tagName.contains(" ")) break;
293→            String closingTag = "</" + tagName + ">";
294→            if (s.endsWith(closingTag)) {
295→                s = s.substring(closeTag + 1, s.length() - closingTag.length()).trim();
296→            } else {
297→                break;
298→            }
299→        } while (!s.equals(prev));
300→        return s.isEmpty() ? output.trim() : s;

