  5→/**
  6→ * Represents a single conversation turn (message) in the conversation.
  7→ * Contains a list of content segments - text, tool calls, and tool results.
  8→ */
  9→public class MessageBlock {
 10→
 11→    /**
 12→     * The role of the message sender.
 13→     */
 14→    public enum Role {
 15→        USER, ASSISTANT, SYSTEM, ERROR
 16→    }
 17→
 18→    /**
 19→     * Status of a tool call.
 20→     */
 21→    public enum ToolStatus {
 22→        RUNNING, COMPLETED, FAILED, NEEDS_PERMISSION
 23→    }
