 25→    private final Role role;
 26→    private final long timestamp;
 27→    private final List<ContentSegment> segments = new ArrayList<>();
 28→
 29→    public MessageBlock(Role role) {
 30→        this.role = role;
 31→        this.timestamp = System.currentTimeMillis();
 32→    }
 33→
 34→    private volatile boolean complete = false;
 35→
 36→    public Role getRole() { return role; }
 37→    public long getTimestamp() { return timestamp; }
 38→    public List<ContentSegment> getSegments() { return segments; }
 39→    public boolean isComplete() { return complete; }
 40→    public void setComplete(boolean complete) { this.complete = complete; }
