 49→    /**
 50→     * Get the last text segment, creating one if the last segment is not text.
 51→     */
 52→    public TextSegment getOrCreateLastTextSegment() {
 53→        if (!segments.isEmpty() && segments.get(segments.size() - 1) instanceof TextSegment) {
 54→            return (TextSegment) segments.get(segments.size() - 1);
 55→        }
 56→        TextSegment textSeg = new TextSegment();
 57→        segments.add(textSeg);
 58→        return textSeg;
