 61→    /**
 62→     * Get all text content concatenated.
 63→     */
 64→    public String getFullText() {
 65→        StringBuilder sb = new StringBuilder();
 66→        for (ContentSegment seg : segments) {
 67→            if (seg instanceof TextSegment) {
 68→                sb.append(((TextSegment) seg).getText());
 69→            }
 70→        }
