120→    /**
121→     * A tool call segment - represents Claude using a tool (Read, Edit, Bash, etc.).
122→     */
123→    public static class ToolCallSegment extends ContentSegment {
124→        private String toolId;
125→        private String toolName;
126→        private String input;           // Tool input (JSON string or description)
127→        private volatile String output;  // Tool result text
128→        private volatile ToolStatus status = ToolStatus.RUNNING;
129→        private final StringBuilder inputBuilder = new StringBuilder();
130→
131→        @Override
132→        public String getSegmentType() { return "tool_use"; }
133→
134→        public String getToolId() { return toolId; }
135→        public void setToolId(String toolId) { this.toolId = toolId; }
136→
137→        public String getToolName() { return toolName; }
138→        public void setToolName(String toolName) { this.toolName = toolName; }
139→
140→        public String getInput() { return input; }
141→        public void setInput(String input) { this.input = input; }
142→
143→        public String getOutput() { return output; }
144→        public void setOutput(String output) { this.output = output; }
145→
146→        public ToolStatus getStatus() { return status; }
147→        public void setStatus(ToolStatus status) { this.status = status; }
148→
149→        /**
150→         * Append incremental tool input (from input_json_delta stream events).
151→         */
152→        public void appendInput(String delta) {
153→            inputBuilder.append(delta);
154→            this.input = inputBuilder.toString();
155→        }
156→
157→        /**
158→         * Get a human-readable display name for the tool.
159→         */
160→        public String getDisplayName() {
161→            if (toolName == null) return "Unknown Tool";
162→            switch (toolName) {
163→                case "Read": return "Read File";
164→                case "Edit": return "Edit File";
165→                case "Write": return "Write File";
166→                case "Bash": return "Run Command";
167→                case "Grep": return "Search Code";
168→                case "Glob": return "Find Files";
169→                case "WebSearch": return "Web Search";
170→                case "WebFetch": return "Fetch URL";
171→                case "Task": return "Sub-Agent";
172→                case "TodoWrite": return "Update Tasks";
173→                default: return toolName;
174→            }
175→        }
176→
177→        /**
178→         * Get a short summary of what the tool is doing.
179→         */
180→        public String getSummary() {
181→            if (input == null || input.isEmpty()) return getDisplayName();
182→            // Try to extract the key parameter for common tools
183→            try {
184→                if ("Read".equals(toolName) || "Write".equals(toolName)) {
185→                    int idx = input.indexOf("file_path");
186→                    if (idx >= 0) {
187→                        String path = extractJsonStringValue(input, "file_path");
188→                        if (path != null) {
189→                            // Show just the filename
190→                            int lastSlash = Math.max(path.lastIndexOf('/'), path.lastIndexOf('\\'));
191→                            return getDisplayName() + ": " + (lastSlash >= 0 ? path.substring(lastSlash + 1) : path);
192→                        }
193→                    }
194→                } else if ("Edit".equals(toolName)) {
195→                    String path = extractJsonStringValue(input, "file_path");
196→                    if (path != null) {
197→                        int lastSlash = Math.max(path.lastIndexOf('/'), path.lastIndexOf('\\'));
198→                        return getDisplayName() + ": " + (lastSlash >= 0 ? path.substring(lastSlash + 1) : path);
199→                    }
200→                } else if ("Bash".equals(toolName)) {
201→                    String cmd = extractJsonStringValue(input, "command");
202→                    if (cmd != null) {
203→                        return getDisplayName() + ": " + (cmd.length() > 60 ? cmd.substring(0, 57) + "..." : cmd);
204→                    }
205→                } else if ("Grep".equals(toolName)) {
206→                    String pattern = extractJsonStringValue(input, "pattern");
207→                    if (pattern != null) {
208→                        return getDisplayName() + ": " + pattern;
209→                    }
210→                }
211→            } catch (Exception ignored) {}
212→            return getDisplayName();
213→        }
214→
215→        private String extractJsonStringValue(String json, String key) {
216→            String marker = "\"" + key + "\":\"";
217→            int start = json.indexOf(marker);
218→            if (start < 0) {
219→                // Try with space after colon
220→                marker = "\"" + key + "\": \"";
221→                start = json.indexOf(marker);
222→            }
223→            if (start < 0) return null;
224→            start += marker.length();
225→            int end = json.indexOf("\"", start);
226→            if (end < 0) return null;
227→            return json.substring(start, end).replace("\\n", "\n").replace("\\\"", "\"");
228→        }
229→    }
