1	package com.anthropic.eclipse.claude.views.widgets;
2	
3	import org.eclipse.swt.SWT;
4	import org.eclipse.swt.custom.StyledText;
5	import org.eclipse.swt.graphics.Color;
6	import org.eclipse.swt.graphics.Font;
7	import org.eclipse.swt.graphics.Point;
8	import org.eclipse.swt.layout.GridData;
9	import org.eclipse.swt.layout.GridLayout;
10	import org.eclipse.swt.widgets.Composite;
11	import org.eclipse.swt.widgets.Display;
12	
13	/**
14	 * A StyledText widget optimized for incremental text append during streaming.
15	 * Buffers deltas for batched append (50ms) to avoid performance issues with
16	 * rapid token-by-token updates.
17	 *
18	 * During streaming: displays raw text with minimal styling.
19	 * After finalize: applies full markdown rendering.
20	 */
21	public class StreamingTextWidget extends Composite {
22	
23	    private StyledText styledText;
24	    private final StringBuilder rawMarkdown = new StringBuilder();
25	    private boolean finalized = false;
26	
27	    // Batching for performance
28	    private final StringBuilder pendingText = new StringBuilder();
29	    private boolean flushScheduled = false;
30	    private static final int FLUSH_DELAY_MS = 50;
31	
32	    public StreamingTextWidget(Composite parent, int style) {
33	        super(parent, SWT.NONE);
34	        GridLayout layout = new GridLayout(1, false);
35	        layout.marginWidth = 0;
36	        layout.marginHeight = 0;
37	        setLayout(layout);
38	        setLayoutData(new GridData(SWT.FILL, SWT.TOP, true, false));
39	
40	        styledText = new StyledText(this, SWT.WRAP | SWT.READ_ONLY | SWT.MULTI);
41	        styledText.setLayoutData(new GridData(SWT.FILL, SWT.TOP, true, false));
42	        styledText.setWordWrap(true);
43	        styledText.setEditable(false);
44	        styledText.setCaret(null);
45	
46	        // Use ThemeManager for colors
47	        ThemeManager tm = ThemeManager.getInstance();
48	        Font font = new Font(parent.getDisplay(), tm.getUIFontName(), 11, SWT.NORMAL);
49	        styledText.setFont(font);
50	        Color textFg = tm.getColor(tm.bodyTextColor);
51	        styledText.setForeground(textFg);
52	        styledText.addDisposeListener(e -> { font.dispose(); textFg.dispose(); });
53	    }
54	
55	    @Override
56	    public Point computeSize(int wHint, int hHint, boolean changed) {
57	        if (wHint == SWT.DEFAULT && getParent() != null && !getParent().isDisposed()) {
58	            int parentWidth = getParent().getClientArea().width;
59	            if (parentWidth > 0) {
60	                wHint = parentWidth;
61	            }
62	        }
63	        return super.computeSize(wHint, hHint, changed);
64	    }
65	
66	    /**
67	     * Append raw text during streaming. Minimal styling for performance.
68	     * Uses batched flush to avoid excessive UI updates.
69	     * Auto-detects RTL on first non-whitespace character.
70	     */
71	    public void appendText(String delta) {
72	        if (finalized || delta == null || delta.isEmpty()) return;
73	
74	        synchronized (pendingText) {
75	            boolean wasEmpty = rawMarkdown.length() == 0;
76	            pendingText.append(delta);
77	            rawMarkdown.append(delta);
78	            if (wasEmpty) {
79	                Display.getDefault().asyncExec(() -> applyRtlIfNeeded(rawMarkdown.toString()));
80	            }
81	        }
82	
83	        if (!flushScheduled && !isDisposed()) {
84	            flushScheduled = true;
85	            Display.getDefault().timerExec(FLUSH_DELAY_MS, this::flushPendingText);
86	        }
87	    }
88	
89	    /**
90	     * After streaming completes, apply full markdown rendering.
91	     */
92	    public void finalizeContent() {
93	        if (finalized) return;
94	        finalized = true;
95	
96	        // Flush any remaining text first
97	        flushPendingText();
98	
99	        // Apply markdown rendering and RTL
100	        if (!styledText.isDisposed()) {
101	            String text = rawMarkdown.toString();
102	            // Duplication guard: if rawMarkdown somehow has doubled content, take only first half
103	            // This can happen on Windows due to CLI sending redundant assistant snapshots
104	            int orientation = detectOrientation(text);
105	            // For RTL: fix leading punctuation (AI generates "?text" instead of "text?")
106	            // and prepend RTL Mark to set bidi base direction on macOS
107	            String renderText = (orientation == SWT.RIGHT_TO_LEFT)
108	                    ? "\u200F" + text  // RTL Mark sets base paragraph direction
109	                    : text;
110	            // Render markdown FIRST (MarkdownRenderer.render calls widget.setText which
111	            // resets orientation/alignment to defaults — we must reapply them afterward).
112	            MarkdownRenderer.render(styledText, renderText);
113	            // Reapply orientation and alignment AFTER setText
114	            styledText.setOrientation(orientation);
115	            styledText.setAlignment(orientation == SWT.RIGHT_TO_LEFT ? SWT.RIGHT : SWT.LEFT);
116	            // Only set RTL on the StyledText itself — do NOT propagate to parent
117	            // composites, as that flips the entire layout (tool calls, buttons, headers)
118	            updateHeight();
119	        }
120	    }
121	
122	    /**
123	     * Detects if text is primarily RTL (Hebrew/Arabic) and sets orientation + alignment.
124	     * Both are needed on macOS where setOrientation alone doesn't reflow visually.
125	     */
126	    private void applyRtlIfNeeded(String text) {
127	        if (styledText == null || styledText.isDisposed()) return;
128	        int orientation = detectOrientation(text);
129	        styledText.setOrientation(orientation);
130	        styledText.setAlignment(orientation == SWT.RIGHT_TO_LEFT ? SWT.RIGHT : SWT.LEFT);
131	        // Only set RTL on StyledText — don't propagate to parents
132	        styledText.redraw();
133	    }
134	
135	    public static int detectOrientation(String text) {
136	        if (text == null) return SWT.LEFT_TO_RIGHT;
137	        // Skip leading punctuation/whitespace to find the first real directional character
138	        for (int i = 0; i < text.length(); i++) {
139	            char c = text.charAt(i);
140	            if (Character.isWhitespace(c) || "?!.,;:\"'()[]{}".indexOf(c) >= 0) continue;
141	            byte dir = Character.getDirectionality(c);
142	            if (dir == Character.DIRECTIONALITY_RIGHT_TO_LEFT
143	                    || dir == Character.DIRECTIONALITY_RIGHT_TO_LEFT_ARABIC
144	                    || dir == Character.DIRECTIONALITY_RIGHT_TO_LEFT_EMBEDDING) {
145	                return SWT.RIGHT_TO_LEFT;
146	            }
147	            return SWT.LEFT_TO_RIGHT;
148	        }
149	        return SWT.LEFT_TO_RIGHT;
150	    }
151	
152	    /**
153	     * AI models often generate RTL text with sentence-ending punctuation (?, !)
154	     * at the start of the string (English convention). This moves them to the end
155	     * so they appear correctly at the visual left in RTL rendering.
156	     */
157	    /**
158	     * Fix punctuation placement in RTL text.
159	     * Claude sometimes generates "?text" instead of "text?" for Hebrew.
160	     * Move leading punctuation to end, and wrap trailing punctuation with
161	     * directional marks so BiDi algorithm places them correctly.
162	     */
163	    private static String fixRtlPunctuation(String text) {
164	        if (text == null || text.isEmpty()) return text;
165	        String[] lines = text.split("\n", -1);
166	        StringBuilder result = new StringBuilder();
167	        for (int lineIdx = 0; lineIdx < lines.length; lineIdx++) {
168	            String line = lines[lineIdx];
169	            // Move leading punctuation to end
170	            int i = 0;
171	            while (i < line.length() && "?!.,:;".indexOf(line.charAt(i)) >= 0) {
172	                i++;
173	            }
174	            if (i > 0 && i < line.length()) {
175	                line = line.substring(i) + line.substring(0, i);
176	            }
177	            // Wrap trailing punctuation with LRM (U+200E) to anchor it at visual end (left in RTL)
178	            if (!line.isEmpty()) {
179	                int end = line.length() - 1;
180	                while (end >= 0 && "?!.,:;".indexOf(line.charAt(end)) >= 0) {
181	                    end--;
182	                }
183	                if (end < line.length() - 1) {
184	                    // Insert LRM before trailing punctuation
185	                    line = line.substring(0, end + 1) + "\u200E" + line.substring(end + 1);
186	                }
187	            }
188	            result.append(line);
189	            if (lineIdx < lines.length - 1) result.append("\n");
190	        }
191	        return result.toString();
192	    }
193	
194	    /**
195	     * Get the raw markdown text accumulated during streaming.
196	     */
197	    public String getRawText() {
198	        return rawMarkdown.toString();
199	    }
200	
201	    /**
202	     * Check if content has been finalized.
203	     */
204	    public boolean isFinalized() {
205	        return finalized;
206	    }
207	
208	    /**
209	     * Get the underlying StyledText widget.
210	     */
211	    public StyledText getStyledText() {
212	        return styledText;
213	    }
214	
215	    // ==================== Internal ====================
216	
217	    private void flushPendingText() {
218	        flushScheduled = false;
219	        if (styledText.isDisposed()) return;
220	
221	        String textToAppend;
222	        synchronized (pendingText) {
223	            if (pendingText.length() == 0) return;
224	            textToAppend = pendingText.toString();
225	            pendingText.setLength(0);
226	        }
227	
228	        styledText.append(textToAppend);
229	        updateHeight();
230	
231	        // Scroll to show latest text
232	        styledText.setTopIndex(styledText.getLineCount() - 1);
233	    }
234	
235	    private void updateHeight() {
236	        // Do not set heightHint — let the StyledText compute its own height
237	        // based on wrapped content. Setting heightHint would use the unwrapped
238	        // line count and produce text that is too short or clips.
239	        if (!isDisposed()) {
240	            getParent().layout(true, true);
241	        }
242	    }
243	}
