public void pasteImage() {
    Clipboard clipboard = new Clipboard(Display.getDefault());
    try {
        ImageData imageData = (ImageData) clipboard.getContents(ImageTransfer.getInstance());
        if (imageData == null) {
            errorCallback.accept("No image found in clipboard.");
            return;
        }
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        ImageLoader loader = new ImageLoader();
        loader.data = new ImageData[]{imageData};
        loader.save(baos, SWT.IMAGE_PNG);  // Converts to PNG format
        byte[] pngBytes = baos.toByteArray();
        images.add(pngBytes);
        String name = "Image " + images.size();
        imageNames.add(name);
        addChip(name + " (" + (pngBytes.length / 1024) + " KB)", () -> {
            // Remove button callback
            int i = images.indexOf(pngBytes);
            if (i >= 0) {
                images.remove(i);
                imageNames.remove(i);
            }
            refresh();
        });
        refresh();
    } catch (Exception ex) {
        errorCallback.accept("Could not paste image: " + ex.getMessage());
    } finally {
        clipboard.dispose();
    }
}
```

