    // Ctrl+V: paste image from clipboard (if clipboard contains an image)
    // Text paste is handled by the default SWT behavior — we only intercept
    // when the clipboard holds an image so users can paste screenshots directly.
    inputField.addListener(SWT.KeyDown, e -> {
        if ((e.stateMask & SWT.MOD1) != 0 && e.keyCode == 'v') {
            Clipboard cb = new Clipboard(Display.getDefault());
            try {
                if (cb.getContents(ImageTransfer.getInstance()) != null) {
                    e.doit = false;
                    if (attachmentManager != null) {
                        attachmentManager.pasteImage();
                    }
                }
                // else: no image — let default text paste proceed
            } finally {
                cb.dispose();
            }
        }
    });

    // Dismiss autocomplete when input loses focus
    inputField.addListener(SWT.FocusOut, e -> {
        Display.getDefault().timerExec(200, () -> dismissAutocomplete());
    });
}

