// Ctrl+Shift+V: paste image from clipboard.
// We use Ctrl+SHIFT+V (not plain Ctrl+V) because the native SWT Text widget
// consumes Ctrl+V for text paste before any Java-level listener can intercept it.
inputField.addListener(SWT.KeyDown, e -> {
    if ((e.stateMask & SWT.MOD1) != 0
            && (e.stateMask & SWT.SHIFT) != 0
            && e.keyCode == 'v') {
        e.doit = false;
        if (attachmentManager != null) {
            attachmentManager.pasteImage();
        }
    }
});

