        connectionStatus.setBackground(viewBgColor);
        connectionStatus.addDisposeListener(e -> statusFont.dispose());

        // Compact icon buttons
        Button newSessionBtn = new Button(toolbar, SWT.PUSH | SWT.FLAT);
        newSessionBtn.setText("+");
