            for (IProject project : projects) {
                if (project.isOpen()) {
                    project.refreshLocal(
                        org.eclipse.core.resources.IResource.DEPTH_INFINITE,
                        null  // no progress monitor
                    );
                }
            }
        } catch (Exception e) {
            Activator.logError("[ConversationView] Workspace refresh failed: " + e.getMessage(), e);
        }
    }

