// Ctrl+V: also paste image when clipboard contains an image (not text).
// Display.addFilter fires BEFORE the native Text widget consumes the keystroke.
// We check both keyCode=='v' and character==0x16 (Ctrl+V) for robustness across
// platforms. We also check isFocusControl() instead of widget identity in case
// SWT reports a different widget handle.
final Text inputRef = inputField; // capture for filter lambda
Display.getDefault().addFilter(SWT.KeyDown, e -> {
    boolean isCtrlV = (e.stateMask & SWT.MOD1) != 0
            && (e.stateMask & SWT.ALT) == 0
            && (e.stateMask & SWT.SHIFT) == 0
            && (e.keyCode == 'v' || e.character == 0x16);
    if (isCtrlV && !inputRef.isDisposed() && inputRef.isFocusControl()) {
        Clipboard cb = new Clipboard(Display.getDefault());
        try {
            if (cb.getContents(ImageTransfer.getInstance()) != null) {
                e.type = SWT.None;
                e.doit = false;
                if (attachmentManager != null) {
                    attachmentManager.pasteImage();
                }
            }
        } finally {
            cb.dispose();
        }
    }
});

// Dismiss autocomplete when input loses focus
inputField.addListener(SWT.FocusOut, e -> {
    Display.getDefault().timerExec(200, () -> dismissAutocomplete());

