    final Text inputRef = inputField;
    Display.getDefault().addFilter(SWT.KeyDown, e -> {
        try {
            java.io.FileWriter fw = new java.io.FileWriter("C:\\temp\\filter_debug.txt", true);
            fw.write("KeyDown: keyCode=" + e.keyCode + " char=" + (int)e.character
                    + " stateMask=" + e.stateMask + " widget=" + e.widget.getClass().getName()
                    + " inputFocus=" + (!inputRef.isDisposed() && inputRef.isFocusControl()) + "\n");
            fw.close();
        } catch (Exception ignored) {}
        boolean isCtrlV = (e.stateMask & SWT.MOD1) != 0
                && (e.stateMask & SWT.ALT) == 0
                && (e.stateMask & SWT.SHIFT) == 0
                && (e.keyCode == 'v' || e.character == 0x16);
        if (isCtrlV && !inputRef.isDisposed() && inputRef.isFocusControl()) {
            try {
                java.io.FileWriter fw2 = new java.io.FileWriter("C:\\temp\\filter_debug.txt", true);
                fw2.write("  -> Ctrl+V detected in input! Checking clipboard...\n");
                fw2.close();
            } catch (Exception ignored) {}
            Clipboard cb = new Clipboard(Display.getDefault());
            try {
                Object imgData = cb.getContents(ImageTransfer.getInstance());
                try {
                    java.io.FileWriter fw3 = new java.io.FileWriter("C:\\temp\\filter_debug.txt", true);
                    fw3.write("  -> imageData=" + (imgData != null ? "FOUND" : "null") + "\n");
                    fw3.close();
                } catch (Exception ignored) {}
                if (imgData != null) {
                    e.type = SWT.None;
                    e.doit = false;
                    if (attachmentManager != null) {
                        attachmentManager.pasteImage();
                    }
                }
            } finally {
                cb.dispose();
            }
        }
    });

    // Dismiss autocomplete when input loses focus
    inputField.addListener(SWT.FocusOut, e -> {
        Display.getDefault().timerExec(200, () -> dismissAutocomplete());
    });
}

