    private static final String[][] AVAILABLE_MODELS = {
        {"claude-sonnet-4-5", "Sonnet 4.5 — Fast, balanced"},
        {"claude-opus-4", "Opus 4 — Most capable"},
        {"claude-haiku-3-5", "Haiku 3.5 — Fastest, lightweight"},
