47	/**
48	 * Manages file and image attachments for the conversation input area.
49	 *
50	 * <p>Encapsulates attachment state (file paths, line ranges, images) and
51	 * provides UI chip management. Created by {@link ClaudeConversationView}
52	 * once the attachment bar composite is available.
53	 */
54	public class AttachmentManager {
55	
56	    // State
57	    private final List<String>       filePaths  = new ArrayList<>();
58	    private final Map<String, int[]> fileRanges = new LinkedHashMap<>();
59	    private final List<byte[]>       images     = new ArrayList<>();
60	    private final List<String>       imageNames = new ArrayList<>();
61	
62	    // UI refs
63	    private final Composite attachmentBar;
64	    private final Shell     shell;
65	    private final Text      inputField;   // needed for @-mention caret manipulation
66	
67	    // Callbacks to owner view
68	    private final Consumer<String> errorCallback;
69	
70	    public AttachmentManager(Composite attachmentBar, Shell shell,
71	                             Text inputField, Consumer<String> errorCallback) {
72	        this.attachmentBar  = attachmentBar;
73	        this.shell          = shell;
74	        this.inputField     = inputField;
75	        this.errorCallback  = errorCallback;
76	    }
77	
78	    // ====== State queries ======
79	
80	    public boolean hasAttachments() {
81	        return !filePaths.isEmpty() || !images.isEmpty();
82	    }
83	
84	    public List<String>       getFilePaths()  { return filePaths; }
85	    public Map<String, int[]> getFileRanges() { return fileRanges; }
86	    public List<byte[]>       getImages()     { return images; }
87	    public List<String>       getImageNames() { return imageNames; }
88	
89	    /**
90	     * Builds a display label like "[file.java#10-20] [Image 1] ".
91	     */
92	    public String buildDisplayLabel() {
93	        StringBuilder sb = new StringBuilder();
94	        for (String path : filePaths) {
95	            int[] range = fileRanges.get(path);
96	            String label = Paths.get(path).getFileName().toString();
97	            if (range != null) label += "#" + range[0] + "-" + range[1];
98	            sb.append("[").append(label).append("] ");
99	        }
100	        for (String name : imageNames) {
101	            sb.append("[").append(name).append("] ");
102	        }
103	        return sb.toString();
104	    }
105	
106	    /**
107	     * Builds the &lt;file&gt; context blocks to prepend to the outgoing message.
108	     */
109	    public String buildFileContext() {
110	        StringBuilder sb = new StringBuilder();
111	        for (String filePath : new ArrayList<>(filePaths)) {
112	            try {
113	                String rawContent = new String(Files.readAllBytes(Paths.get(filePath)), StandardCharsets.UTF_8);
114	                String fileName   = Paths.get(filePath).getFileName().toString();
115	                int[]  range      = fileRanges.get(filePath);
116	                String content;
117	                String fileLabel;
118	                if (range != null) {
119	                    String[] fileLines = rawContent.split("\n", -1);
120	                    int start = Math.max(1, range[0]);
121	                    int end   = Math.min(fileLines.length, range[1]);
122	                    StringBuilder lineSb = new StringBuilder();
123	                    for (int li = start - 1; li < end; li++) {
124	                        lineSb.append(fileLines[li]).append("\n");
125	                    }
126	                    content   = lineSb.toString();
127	                    fileLabel = fileName + " (lines " + start + "-" + end + ")";
128	                } else {
129	                    content   = rawContent;
130	                    fileLabel = fileName;
131	                }
132	                if (content.length() > 50_000) {
133	                    content = content.substring(0, 50_000) + "\n... [truncated]";
134	                }
135	                sb.append("<file path=\"").append(fileLabel).append("\">\n");
136	                sb.append(content).append("</file>\n\n");
137	            } catch (Exception ex) {
138	                sb.append("[Could not read: ").append(Paths.get(filePath).getFileName()).append("]\n\n");
139	            }
140	        }
141	        return sb.toString();
142	    }
143	
144	    /** Clears all attachment state and removes UI chips. */
145	    public void clearAll() {
146	        filePaths.clear();
147	        fileRanges.clear();
148	        images.clear();
149	        imageNames.clear();
150	        clearChips();
151	    }
152	
153	    // ====== UI actions ======
154	
155	    /** Show a popup menu to choose between workspace files or filesystem browse. */
156	    public void attachFile() {
157	        Menu menu = new Menu(shell, SWT.POP_UP);
158	
159	        MenuItem workspaceItem = new MenuItem(menu, SWT.PUSH);
160	        workspaceItem.setText("From Workspace...");
161	        workspaceItem.addListener(SWT.Selection, e -> attachFileFromWorkspace());
162	
163	        MenuItem filesystemItem = new MenuItem(menu, SWT.PUSH);
164	        filesystemItem.setText("Browse Filesystem...");
165	        filesystemItem.addListener(SWT.Selection, e -> attachFileFromFilesystem());
166	
167	        // Show at current cursor position
168	        org.eclipse.swt.graphics.Point pt = Display.getCurrent().getCursorLocation();
169	        menu.setLocation(pt.x, pt.y);
170	        menu.setVisible(true);
171	    }
172	
173	    /** Open an Eclipse tree dialog to pick one or more workspace files. */
174	    private void attachFileFromWorkspace() {
175	        ElementTreeSelectionDialog dialog = new ElementTreeSelectionDialog(
176	            shell, new WorkbenchLabelProvider(), new WorkbenchContentProvider());
177	        dialog.setTitle("Add File to Context");
178	        dialog.setMessage("Select one or more files to include in your message:");
179	        dialog.setInput(ResourcesPlugin.getWorkspace().getRoot());
180	        dialog.addFilter(new ViewerFilter() {
181	            @Override
182	            public boolean select(Viewer viewer, Object parentElement, Object element) {
183	                return element instanceof org.eclipse.core.resources.IContainer
184	                    || element instanceof IFile;
185	            }
186	        });
187	        dialog.setAllowMultiple(true);
188	
189	        if (dialog.open() == Window.OK) {
190	            for (Object result : dialog.getResult()) {
191	                if (result instanceof IFile) {
192	                    IFile iFile = (IFile) result;
193	                    String path = iFile.getLocation().toOSString();
194	                    if (!filePaths.contains(path)) {
195	                        filePaths.add(path);
196	                        addChip(iFile.getName(), () -> {
197	                            filePaths.remove(path);
198	                            refresh();
199	                        });
200	                    }
201	                }
202	            }
203	            refresh();
204	        }
205	    }
206	
207	    /** Open a native OS file dialog to pick any file from the filesystem. */
208	    private void attachFileFromFilesystem() {
209	        FileDialog dialog = new FileDialog(shell, SWT.OPEN | SWT.MULTI);
210	        dialog.setText("Add File to Context");
211	        String firstPath = dialog.open();
212	        if (firstPath != null) {
213	            String filterPath = dialog.getFilterPath();
214	            for (String fileName : dialog.getFileNames()) {
215	                String fullPath = filterPath + java.io.File.separator + fileName;
216	                if (!filePaths.contains(fullPath)) {
217	                    filePaths.add(fullPath);
218	                    final String capturedPath = fullPath;
219	                    addChip(fileName, () -> {
220	                        filePaths.remove(capturedPath);
221	                        refresh();
222	                    });
223	                }
224	            }
225	            refresh();
226	        }
227	    }
228	
229	    /** Open a quick list dialog to attach a file via @-mention. */
230	    public void handleAtMention() {
231	        if (inputField == null || inputField.isDisposed()) return;
232	
233	        List<IFile> allFiles = new ArrayList<>();
234	        IProject[] projects = ResourcesPlugin.getWorkspace().getRoot().getProjects();
235	        for (IProject project : projects) {
236	            if (project.isOpen()) {
237	                try {
238	                    collectFiles(project, allFiles, 500);
239	                } catch (Exception ignored) {}
240	            }
241	        }
242	        if (allFiles.isEmpty()) return;
243	
244	        ElementListSelectionDialog dialog = new ElementListSelectionDialog(
245	            shell, new LabelProvider() {
246	                @Override
247	                public String getText(Object element) {
248	                    if (element instanceof IFile) {
249	                        IFile f = (IFile) element;
250	                        return f.getName() + " - " + f.getProjectRelativePath().toString();
251	                    }
252	                    return super.getText(element);
253	                }
254	            });
255	        dialog.setTitle("@mention - Select File");
256	        dialog.setMessage("Type to filter, select a file to attach:");
257	        dialog.setElements(allFiles.toArray());
258	        dialog.setMultipleSelection(true);
259	
260	        if (dialog.open() == Window.OK) {
261	            for (Object result : dialog.getResult()) {
262	                if (result instanceof IFile) {
263	                    IFile iFile = (IFile) result;
264	                    String path = iFile.getLocation().toOSString();
265	                    if (!filePaths.contains(path)) {
266	                        int[] range = askForLineRange(iFile.getName());
267	                        filePaths.add(path);
268	                        if (range != null) fileRanges.put(path, range);
269	                        String chipLabel = range != null
270	                            ? iFile.getName() + "#" + range[0] + "-" + range[1]
271	                            : iFile.getName();
272	                        addChip(chipLabel, () -> {
273	                            filePaths.remove(path);
274	                            fileRanges.remove(path);
275	                            refresh();
276	                        });
277	                    }
278	                }
279	            }
280	            refresh();
281	
282	            // Remove the @ character from input
283	            String currentText = inputField.getText();
284	            int caretPos = inputField.getCaretPosition();
285	            if (caretPos > 0 && caretPos <= currentText.length()
286	                    && currentText.charAt(caretPos - 1) == '@') {
287	                inputField.setText(currentText.substring(0, caretPos - 1)
288	                    + currentText.substring(caretPos));
289	                inputField.setSelection(caretPos - 1);
290	            }
291	        }
292	    }
293	
294	    /** Paste an image from the system clipboard. */
295	    public void pasteImage() {
296	        Clipboard clipboard = new Clipboard(Display.getDefault());
297	        try {
298	            ImageData imageData = (ImageData) clipboard.getContents(ImageTransfer.getInstance());
299	            if (imageData == null) {
300	                errorCallback.accept("No image found in clipboard.\n" +
301	                    "Copy an image first (e.g. Cmd+Ctrl+Shift+4 for a screenshot), then try again.");
302	                return;
303	            }
304	            ByteArrayOutputStream baos = new ByteArrayOutputStream();
305	            ImageLoader loader = new ImageLoader();
306	            loader.data = new ImageData[]{imageData};
307	            loader.save(baos, SWT.IMAGE_PNG);
308	            byte[] pngBytes = baos.toByteArray();
309	            images.add(pngBytes);
310	            String name = "Image " + images.size();
311	            imageNames.add(name);
312	            addChip(name + " (" + (pngBytes.length / 1024) + " KB)", () -> {
313	                int i = images.indexOf(pngBytes);
314	                if (i >= 0) {
315	                    images.remove(i);
316	                    imageNames.remove(i);
317	                }
318	                refresh();
319	            });
320	            refresh();
321	        } catch (Exception ex) {
322	            errorCallback.accept("Could not paste image: " + ex.getMessage());
323	        } finally {
324	            clipboard.dispose();
325	        }
326	    }
327	
328	    // ====== private helpers ======
329	
330	    private int[] askForLineRange(String fileName) {
331	        InputDialog rangeDialog = new InputDialog(
332	            shell,
333	            "Line Range (optional)",
334	            "Include specific lines of " + fileName + "?\n" +
335	            "Enter range like \"10-20\", or leave empty for the whole file:",
336	            "",
337	            newText -> {
338	                if (newText == null || newText.trim().isEmpty()) return null;
339	                String[] parts = newText.trim().split("-");
340	                if (parts.length != 2) return "Format must be 'start-end' (e.g. 10-20)";
341	                try {
342	                    int start = Integer.parseInt(parts[0].trim());
343	                    int end   = Integer.parseInt(parts[1].trim());
344	                    if (start < 1 || end < start)
345	                        return "Invalid range: start must be >= 1 and end >= start";
346	                } catch (NumberFormatException ex) {
347	                    return "Line numbers must be integers";
348	                }
349	                return null;
350	            });
351	        if (rangeDialog.open() != Window.OK) return null;
352	        String value = rangeDialog.getValue().trim();
353	        if (value.isEmpty()) return null;
354	        try {
355	            String[] parts = value.split("-");
356	            return new int[]{ Integer.parseInt(parts[0].trim()), Integer.parseInt(parts[1].trim()) };
357	        } catch (Exception e) {
358	            return null;
359	        }
360	    }
361	
362	    private void addChip(String label, Runnable onRemove) {
363	        ThemeManager tmChip = ThemeManager.getInstance();
364	        Color chipBg = tmChip.getColor(tmChip.chipBg);
365	        Composite chip = new Composite(attachmentBar, SWT.BORDER);
366	        GridLayout chipLayout = new GridLayout(2, false);
367	        chipLayout.marginWidth = 5;
368	        chipLayout.marginHeight = 2;
369	        chipLayout.horizontalSpacing = 2;
370	        chip.setLayout(chipLayout);
371	        chip.setBackground(chipBg);
372	        chip.addDisposeListener(e -> chipBg.dispose());
373	
374	        Label chipLabel = new Label(chip, SWT.NONE);
375	        chipLabel.setText(label);
376	        chipLabel.setBackground(chipBg);
377	        Font chipFont = new Font(Display.getDefault(), "Segoe UI", 8, SWT.NORMAL);
378	        chipLabel.setFont(chipFont);
379	        chipLabel.addDisposeListener(e -> chipFont.dispose());
380	
381	        Button removeBtn = new Button(chip, SWT.FLAT);
382	        removeBtn.setText("\u00D7");
383	        removeBtn.setBackground(chipBg);
384	        removeBtn.addListener(SWT.Selection, e -> {
385	            onRemove.run();
386	            chip.dispose();
387	            refresh();
388	        });
389	    }
390	
391	    private void refresh() {
392	        if (attachmentBar == null || attachmentBar.isDisposed()) return;
393	        boolean hasChips = attachmentBar.getChildren().length > 0;
394	        GridData gd = (GridData) attachmentBar.getLayoutData();
395	        gd.exclude = !hasChips;
396	        attachmentBar.setVisible(hasChips);
397	        attachmentBar.getParent().layout(true, true);
398	    }
399	
400	    private void clearChips() {
401	        if (attachmentBar == null || attachmentBar.isDisposed()) return;
402	        for (Control child : attachmentBar.getChildren()) {
403	            child.dispose();
404	        }
405	        refresh();
406	    }
407	
408	    private static void collectFiles(org.eclipse.core.resources.IContainer container,
409	                                     List<IFile> files, int maxFiles) {
410	        if (files.size() >= maxFiles) return;
411	        try {
412	            for (org.eclipse.core.resources.IResource member : container.members()) {
413	                if (files.size() >= maxFiles) break;
414	                if (member instanceof IFile) {
415	                    files.add((IFile) member);
416	                } else if (member instanceof org.eclipse.core.resources.IContainer) {
417	                    String name = member.getName();
418	                    if (!name.startsWith(".") && !"bin".equals(name)
419	                            && !"target".equals(name) && !"node_modules".equals(name)) {
420	                        collectFiles((org.eclipse.core.resources.IContainer) member, files, maxFiles);
421	                    }
422	                }
423	            }
424	        } catch (Exception ignored) {}
425	    }
426	}
