// Enter handling via Verify: intercepts BEFORE the newline character is
// inserted into the native Text widget, so we can reliably block it.
// - Enter (any)        = send (unless autocomplete is open)
// - Shift+Enter (any)  = newline (allow through)
inputField.addListener(SWT.Verify, e -> {
    // Verify fires with e.text containing the character(s) to be inserted.
    // For Enter keys, e.text is "\r\n" or "\n" or "\r".
    if (e.text != null && (e.text.equals("\r\n") || e.text.equals("\n") || e.text.equals("\r"))) {
        boolean shiftDown = (e.stateMask & SWT.SHIFT) != 0;
        if (shiftDown) {
            return; // allow newline insertion
        }
        // Don't send if autocomplete is open — Enter there selects the command
        if (autocompletePopup != null && !autocompletePopup.isDisposed()
                && autocompletePopup.isVisible()) {
            return;
        }
        e.doit = false; // block the newline character
        Display.getDefault().asyncExec(() -> handleInput());
    }

