// Enter handling: Enter sends, Shift+Enter inserts newline.
// On Windows, Verify event's stateMask may not reflect Shift state for
// native Text widgets, so we track Shift state via Display filters.
final boolean[] shiftHeld = {false};
Display.getDefault().addFilter(SWT.KeyDown, e -> {
    if (e.keyCode == SWT.SHIFT) shiftHeld[0] = true;
    try {
        java.io.FileWriter fw = new java.io.FileWriter("C:\\temp\\enter_debug.txt", true);
        fw.write("FILTER KeyDown: keyCode=" + e.keyCode + " char=" + (int)e.character
                + " stateMask=" + e.stateMask + " shiftHeld=" + shiftHeld[0] + "\n");
        fw.close();
    } catch (Exception ignored) {}
});
Display.getDefault().addFilter(SWT.KeyUp, e -> {
    if (e.keyCode == SWT.SHIFT) shiftHeld[0] = false;
});
inputField.addListener(SWT.Verify, e -> {
    try {
        java.io.FileWriter fw = new java.io.FileWriter("C:\\temp\\enter_debug.txt", true);
        fw.write("VERIFY: text='" + (e.text == null ? "null" : e.text.replace("\r","\\r").replace("\n","\\n"))
                + "' stateMask=" + e.stateMask + " shiftHeld=" + shiftHeld[0] + "\n");
        fw.close();
    } catch (Exception ignored) {}
    if (e.text != null && (e.text.equals("\r\n") || e.text.equals("\n") || e.text.equals("\r"))) {
        if (shiftHeld[0]) {
            return; // Shift+Enter: allow newline insertion
        }
        if (autocompletePopup != null && !autocompletePopup.isDisposed()
                && autocompletePopup.isVisible()) {
            return;
        }
        e.doit = false;
        Display.getDefault().asyncExec(() -> handleInput());
    }
});

