// Enter handling: Enter sends, Shift+Enter inserts newline.
// On Windows, the native Text widget ignores Shift+Enter entirely (no Verify
// event fires, no newline inserted). So we handle both cases:
// 1. Display filter: Shift+Enter → manually insert newline
// 2. Verify listener: plain Enter → block newline and send
final Text enterInputRef = inputField;
Display.getDefault().addFilter(SWT.KeyDown, e -> {
    if ((e.keyCode == SWT.CR || e.keyCode == SWT.LF || e.keyCode == SWT.KEYPAD_CR)
            && (e.stateMask & SWT.SHIFT) != 0
            && !enterInputRef.isDisposed() && enterInputRef.isFocusControl()) {
        // Shift+Enter: manually insert newline at caret position
        e.type = SWT.None;
        e.doit = false;
        Display.getDefault().asyncExec(() -> {
            if (enterInputRef.isDisposed()) return;
            org.eclipse.swt.graphics.Point sel = enterInputRef.getSelection();
            String text = enterInputRef.getText();
            String before = text.substring(0, sel.x);
            String after = text.substring(sel.y);
            enterInputRef.setText(before + "\n" + after);
            enterInputRef.setSelection(sel.x + 1);
        });
    }
});
inputField.addListener(SWT.Verify, e -> {
    // Plain Enter: Verify fires with "\r\n" — block it and send.
    if (e.text != null && (e.text.equals("\r\n") || e.text.equals("\n") || e.text.equals("\r"))) {
        if (autocompletePopup != null && !autocompletePopup.isDisposed()
                && autocompletePopup.isVisible()) {
            return;
        }
        e.doit = false;
        Display.getDefault().asyncExec(() -> handleInput());
    }
});

