    if (e.keyCode == SWT.CR || e.keyCode == SWT.LF || e.keyCode == SWT.KEYPAD_CR) {
        boolean enterToSend = Activator.getDefault().getPreferenceStore()
                .getBoolean(PreferenceConstants.ENTER_TO_SEND);
