// Clear input and preserve the keyboard language (e.g. Hebrew).
// On Windows, setText("") resets the input language asynchronously.
// We save the keyboard layout and restore it after a short delay.
inputField.setText("");
if (SWT.getPlatform().equals("win32")) {
    try {
        // Get layout BEFORE Windows processes the change
        long hkl = org.eclipse.swt.internal.win32.OS.GetKeyboardLayout(0);
        try {
            java.io.FileWriter fw = new java.io.FileWriter("C:\\temp\\kbd_debug.txt", true);
            fw.write("hkl=" + hkl + " (0x" + Long.toHexString(hkl) + ")\n");
            fw.close();
        } catch (Exception ignored) {}
        Display.getDefault().timerExec(50, () -> {
            try {
                long result = org.eclipse.swt.internal.win32.OS.ActivateKeyboardLayout(hkl, 0);
                java.io.FileWriter fw2 = new java.io.FileWriter("C:\\temp\\kbd_debug.txt", true);
                fw2.write("restored hkl=" + hkl + " result=" + result + "\n");
                fw2.close();
            } catch (Throwable ignored) {}
        });
    } catch (Throwable t) {
        try {
            java.io.FileWriter fw = new java.io.FileWriter("C:\\temp\\kbd_debug.txt", true);
            fw.write("ERROR: " + t.getClass().getName() + ": " + t.getMessage() + "\n");
            fw.close();
        } catch (Exception ignored) {}
    }
}

