        String diagnosis = diagnoseCrash(exitCode);
        msg.setText("\u26A0 Claude CLI terminated" + (exitCode >= 0 ? " (exit " + exitCode + ")" : "") + ".\n" + diagnosis);
        msg.setLayoutData(new GridData(SWT.FILL, SWT.CENTER, true, false));
