// ==================== Message Handling ====================

private void handleInput() {
    String text = inputField.getText().trim();
    boolean hasAttachments = attachmentManager != null && attachmentManager.hasAttachments();
    if (text.isEmpty() && !hasAttachments) return;

    dismissAutocomplete();
    // Clear input and preserve the keyboard language (e.g. Hebrew).
    // On Windows, setText("") resets the input language. We save the
    // keyboard layout BEFORE clearing, then restore aggressively.
    long savedHkl = 0;
    if (SWT.getPlatform().equals("win32")) {
        try {
            savedHkl = org.eclipse.swt.internal.win32.OS.GetKeyboardLayout(0);
        } catch (Throwable ignored) {}
    }
    inputField.setText("");
    if (savedHkl != 0) {
        final long hkl = savedHkl;
        final long shellHwnd = inputField.getShell().handle;
        try {
            // Restore immediately
            org.eclipse.swt.internal.win32.OS.ActivateKeyboardLayout(hkl, 0);
            // Also send WM_INPUTLANGCHANGEREQUEST to the shell (top-level window)
            org.eclipse.swt.internal.win32.OS.SendMessage(shellHwnd, /*WM_INPUTLANGCHANGEREQUEST*/ 0x0050, 0, hkl);
        } catch (Throwable ignored) {}
        // Backup: restore again after async processing
        Display.getDefault().asyncExec(() -> {
            try {
                org.eclipse.swt.internal.win32.OS.ActivateKeyboardLayout(hkl, 0);
            } catch (Throwable ignored) {}
        });
    }

    // Check for slash commands (only when no attachments)
    if (!hasAttachments && text.startsWith("/")) {
        if (handleSlashCommand(text)) return;
    }

    // Ensure CLI is running
    if (!cliManager.isRunning()) {
        autoStartCli();
        if (!cliManager.isRunning()) {
            showError("Claude CLI is not running. Please check your configuration.");
            return;
        }
    }

    // Build message text - prepend active editor context + embed file contents inline
    StringBuilder fullMessage = new StringBuilder();

    // Inject active editor context so Claude knows which file the user is looking at
    String editorContext = getActiveEditorContext();

