                // GetKeyState high bit = key is currently down.
                boolean altDown = (org.eclipse.swt.internal.win32.OS.GetKeyState(0x12 /*VK_MENU*/) & 0x8000) != 0;
                boolean ctrlDown = (org.eclipse.swt.internal.win32.OS.GetKeyState(0x11 /*VK_CONTROL*/) & 0x8000) != 0;
                boolean winDown = (org.eclipse.swt.internal.win32.OS.GetKeyState(0x5B /*VK_LWIN*/) & 0x8000) != 0
                        || (org.eclipse.swt.internal.win32.OS.GetKeyState(0x5C /*VK_RWIN*/) & 0x8000) != 0;
                if (altDown || ctrlDown || winDown) {
                    // User-initiated language switch — allow and save
                    savedInputHkl[0] = lParam;
