        long wndProc(long hWnd, long msg, long wParam, long lParam) {
            if (msg == 0x0302 /* WM_PASTE */) {
                Clipboard cb = new Clipboard(Display.getDefault());
                try {
                    if (cb.getContents(ImageTransfer.getInstance()) != null) {
                        if (amRef != null) {
                            amRef.pasteImage();
                        }
                        return 0;
                    }
                } finally {
                    cb.dispose();
                }
            }
            if (msg == 0x0051 /* WM_INPUTLANGCHANGE */ && !restoringLang[0]) {
                // Check if user intentionally switched language via
                // Alt+Shift, Ctrl+Shift, or Win+Space.
                boolean altDown = (org.eclipse.swt.internal.win32.OS.GetKeyState(0x12) & 0x8000) != 0;
                boolean ctrlDown = (org.eclipse.swt.internal.win32.OS.GetKeyState(0x11) & 0x8000) != 0;
                boolean winDown = (org.eclipse.swt.internal.win32.OS.GetKeyState(0x5B) & 0x8000) != 0
                        || (org.eclipse.swt.internal.win32.OS.GetKeyState(0x5C) & 0x8000) != 0;
                if (altDown || ctrlDown || winDown) {
                    // User-initiated language switch — allow and save
                    savedInputHkl[0] = lParam;
                } else {
                    // System-initiated — block and restore with reentrancy guard
                    restoringLang[0] = true;
                    try {
                        org.eclipse.swt.internal.win32.OS.ActivateKeyboardLayout(savedInputHkl[0], 0);
                    } finally {
                        restoringLang[0] = false;
                    }
                    return 1;
                }
            }
            return org.eclipse.swt.internal.win32.OS.CallWindowProc(
                    oldWndProc[0], hWnd, (int)msg, wParam, lParam);
        }
    }, "wndProc", 4);

