    @Override
    public void onConversationCleared() {
        asyncExec(() -> {
            for (MessageComposite widget : messageWidgetMap.values()) {
                if (!widget.isDisposed()) widget.dispose();
            }
            messageWidgetMap.clear();
            toolCallWidgetById.clear();
