if (SWT.getPlatform().equals("win32")) {
    final long[] lastInputHkl = {0};
    final String DBG = "C:\\temp\\kbd_focus_debug.txt";
    try {
        lastInputHkl[0] = org.eclipse.swt.internal.win32.OS.GetKeyboardLayout(0);
