    inputField.addListener(SWT.KeyDown, e -> {
        try {
            lastInputHkl[0] = org.eclipse.swt.internal.win32.OS.GetKeyboardLayout(0);
            new java.io.FileWriter(DBG, true).append("KeyDown: saved hkl=0x" + Long.toHexString(lastInputHkl[0]) + "\n").close();
