        if (lastInputHkl[0] != 0) {
            try {
                org.eclipse.swt.internal.win32.OS.ActivateKeyboardLayout(lastInputHkl[0], 0);
                long after = org.eclipse.swt.internal.win32.OS.GetKeyboardLayout(0);
