            } catch (Throwable ignored) {}
        }
    });
    inputField.addListener(SWT.FocusOut, e -> {
        try {
            new java.io.FileWriter(DBG, true).append("FocusOut!\n").close();
        } catch (Throwable ignored) {}
    });
}

