private boolean handleSlashCommand(String input) {
    String[] parts = input.split("\\s+", 2);
    String command = parts[0].toLowerCase();

    switch (command) {
        case "/new":
            startNewSession();
            return true;
        case "/clear":
            clearConversation();
            return true;
