long wndProc(long hWnd, long msg, long wParam, long lParam) {
    if (msg == 0x0302 /* WM_PASTE */) {
        Clipboard cb = new Clipboard(Display.getDefault());
        try {
            if (cb.getContents(ImageTransfer.getInstance()) != null) {
                if (amRef != null) {
                    amRef.pasteImage();
                }
                return 0;
            }
        } finally {
            cb.dispose();
        }
    }
    // DEBUG: log all language-related messages
    if (msg == 0x0050 /* WM_INPUTLANGCHANGEREQUEST */) {
        System.err.println("[LANG-DEBUG] WM_INPUTLANGCHANGEREQUEST wParam=0x" + Long.toHexString(wParam) + " lParam=0x" + Long.toHexString(lParam) + " block=" + self.blockLanguageChange);
        if (self.blockLanguageChange) {
            System.err.println("[LANG-DEBUG] BLOCKED WM_INPUTLANGCHANGEREQUEST");
            return 0;
        }
    }
    if (msg == 0x0051 /* WM_INPUTLANGCHANGE */) {
        System.err.println("[LANG-DEBUG] WM_INPUTLANGCHANGE newLang=0x" + Long.toHexString(lParam) + " block=" + self.blockLanguageChange);
    }
    if (msg == 0x0008 /* WM_KILLFOCUS */) {
        long curHkl = 0;
        try { curHkl = org.eclipse.swt.internal.win32.OS.GetKeyboardLayout(0); } catch (Throwable ignored) {}
        System.err.println("[LANG-DEBUG] WM_KILLFOCUS hkl=0x" + Long.toHexString(curHkl));
    }
    if (msg == 0x0007 /* WM_SETFOCUS */) {
        long curHkl = 0;
        try { curHkl = org.eclipse.swt.internal.win32.OS.GetKeyboardLayout(0); } catch (Throwable ignored) {}
        System.err.println("[LANG-DEBUG] WM_SETFOCUS hkl=0x" + Long.toHexString(curHkl) + " pendingRestore=0x" + Long.toHexString(self.pendingRestoreHkl));
        if (self.pendingRestoreHkl != 0) {
            long result = org.eclipse.swt.internal.win32.OS.CallWindowProc(
                    oldWndProc[0], hWnd, (int)msg, wParam, lParam);
            org.eclipse.swt.internal.win32.OS.ActivateKeyboardLayout(self.pendingRestoreHkl, 0);
            System.err.println("[LANG-DEBUG] Restored hkl to 0x" + Long.toHexString(self.pendingRestoreHkl));
            return result;
        }
    }
    return org.eclipse.swt.internal.win32.OS.CallWindowProc(
            oldWndProc[0], hWnd, (int)msg, wParam, lParam);
}

