// ==================== Message Handling ====================

private void handleInput() {
    String text = inputField.getText().trim();
    boolean hasAttachments = attachmentManager != null && attachmentManager.hasAttachments();
    if (text.isEmpty() && !hasAttachments) return;

    dismissAutocomplete();
    // Save keyboard layout and block language changes during send.
    if (SWT.getPlatform().equals("win32")) {
        try {
            pendingRestoreHkl = org.eclipse.swt.internal.win32.OS.GetKeyboardLayout(0);
            blockLanguageChange = true;
        } catch (Throwable ignored) {}
    }
    inputField.setText("");
    // Restore keyboard layout after setText clears the field.
    // When Enter is pressed, focus stays on the input field so FocusIn
    // never fires. We must explicitly restore the keyboard layout here.
    // Use asyncExec so it runs after any pending Windows messages that
    // may change the language (like WM_INPUTLANGCHANGE from setText).
    if (SWT.getPlatform().equals("win32") && pendingRestoreHkl != 0) {
        final long hklToRestore = pendingRestoreHkl;
        Display.getDefault().asyncExec(() -> {
            try {
                org.eclipse.swt.internal.win32.OS.ActivateKeyboardLayout(hklToRestore, 0);
            } catch (Throwable ignored) {}
        });
    }

