    if (pendingRestoreHkl != 0 && SWT.getPlatform().equals("win32")) {
        final long hkl = pendingRestoreHkl;
        try {
            org.eclipse.swt.internal.win32.OS.ActivateKeyboardLayout(hkl, 0);
