        rowLayout.marginWidth = 0;
        rowLayout.marginHeight = 2;
        attachmentBar.setLayout(rowLayout);
        GridData abGd = new GridData(SWT.FILL, SWT.CENTER, true, false);
        abGd.exclude = true;
        attachmentBar.setLayoutData(abGd);
